133	  List<ExecutableElement> findAnnotatedElementsInClasses(
134	      Set<String> classNames, Class<? extends Annotation> annotationClass) {
135	    List<ExecutableElement> result = new ArrayList<>();
136	    for (String glideExtensionClassName : classNames) {
137	      TypeElement glideExtension =
138	          processingEnv.getElementUtils().getTypeElement(glideExtensionClassName);
139	      for (Element element : glideExtension.getEnclosedElements()) {
140	        if (element.getAnnotation(annotationClass) != null) {
141	          result.add((ExecutableElement) element);
