153	  /**
154	   * Generates a Javadoc code block for generated methods that delegate to methods in {@link
155	   * GlideExtension}s.
156	   *
157	   * <p>The generated block looks something like this:
158	   *
159	   * <pre>
160	   * <code>
161	   *   {@literal @see} com.extension.package.name.ExtensionClassName#extensionMethod(arg1, argN)
162	   * </code>
163	   * </pre>
164	   *
165	   * @param method The method from the {@link GlideExtension} annotated class that the generated
166	   *     method this Javadoc will be attached to delegates to.
167	   */
168	  CodeBlock generateSeeMethodJavadoc(ExecutableElement method) {
169	    // Use the simple name of the containing type instead of just the containing type's TypeMirror
170	    // so that we avoid appending <CHILD> or other type arguments to the class and breaking
171	    // Javadoc's linking.
172	    // With this we get @see RequestOptions#methodName().
173	    // With just ClassName.get(element.getEnclosingElement().asType()), we get:
174	    // @see RequestOptions<CHILD>#methodName().
175	    return generateSeeMethodJavadoc(
176	        getJavadocSafeName(method.getEnclosingElement()),
177	        method.getSimpleName().toString(),
178	        method.getParameters());
179	  }
180	
181	  /**
182	   * Generates a Javadoc block for generated methods that delegate to other methods.
183	   *
184	   * <p>The generated block looks something like this:
185	   *
186	   * <pre>
187	   * <code>
188	   *     {@literal @see} com.package.ClassContainingMethod.methodSimpleName(
189	   *         methodParam1, methodParamN)
190	   * </code>
191	   * </pre>
192	   *
193	   * @param nameOfClassContainingMethod The simple class name of the class containing the method
194	   *     without any generic types like {@literal <T>}.
195	   * @param methodSimpleName The name of the method.
196	   * @param methodParameters A maybe empty list of all the parameters for the method in question.
197	   */
198	  CodeBlock generateSeeMethodJavadoc(
199	      TypeName nameOfClassContainingMethod,
200	      String methodSimpleName,
201	      List<? extends VariableElement> methodParameters) {
202	    return generateSeeMethodJavadocInternal(
203	        nameOfClassContainingMethod,
204	        methodSimpleName,
205	        Lists.transform(
206	            methodParameters,
207	            new Function<VariableElement, Object>() {
208	              @Override
209	              public Object apply(VariableElement input) {
210	                return getJavadocSafeName(input);
211	              }
212	            }));
213	  }
214	
215	  CodeBlock generateSeeMethodJavadoc(TypeName nameOfClassContainingMethod, MethodSpec methodSpec) {
216	    return generateSeeMethodJavadocInternal(
217	        nameOfClassContainingMethod,
218	        methodSpec.name,
219	        Lists.transform(
220	            methodSpec.parameters,
221	            new Function<ParameterSpec, Object>() {
222	              @Override
223	              public Object apply(ParameterSpec input) {
224	                return input.type;
225	              }
226	            }));
227	  }
