229	  private CodeBlock generateSeeMethodJavadocInternal(
230	      TypeName nameOfClassContainingMethod, String methodName, List<Object> safeParameterNames) {
231	    StringBuilder javadocString = new StringBuilder("@see $T#$L(");
232	    List<Object> javadocArgs = new ArrayList<>();
233	    javadocArgs.add(nameOfClassContainingMethod);
234	    javadocArgs.add(methodName);
235	
236	    for (Object param : safeParameterNames) {
237	      javadocString.append("$T, ");
238	      javadocArgs.add(param);
239	    }
240	    if (javadocArgs.size() > 2) {
241	      javadocString = new StringBuilder(javadocString.substring(0, javadocString.length() - 2));
242	    }
243	    javadocString.append(")\n");
244	    return CodeBlock.of(javadocString.toString(), javadocArgs.toArray(new Object[0]));
245	  }
