247	  /**
248	   * Returns a safe String to use in a Javadoc that will function in a link.
249	   *
250	   * <p>This method exists because by Javadoc doesn't handle type parameters({@literal <T>} in
251	   * {@literal RequestOptions<T>} for example).
252	   */
253	  private TypeName getJavadocSafeName(Element element) {
254	    Types typeUtils = processingEnv.getTypeUtils();
255	    TypeMirror type = element.asType();
256	    if (typeUtils.asElement(type) == null) {
257	      // If there is no Element, it's a primitive and can't have additional types, so we're done.
258	      return ClassName.get(element.asType());
259	    }
260	    Name simpleName = typeUtils.asElement(type).getSimpleName();
261	    return ClassName.bestGuess(simpleName.toString());
262	  }
