274	  static CodeBlock generateCastingSuperCall(TypeName toReturn, MethodSpec method) {
275	    return CodeBlock.builder()
276	        .add("return ($T) super.$N(", toReturn, method.name)
277	        .add(
278	            FluentIterable.from(method.parameters)
279	                .transform(
280	                    new Function<ParameterSpec, String>() {
281	                      @Override
282	                      public String apply(ParameterSpec input) {
283	                        return input.name;
284	                      }
285	                    })
286	                .join(Joiner.on(",")))
287	        .add(");\n")
288	        .build();
289	  }
