291	  MethodSpec.Builder overriding(ExecutableElement method) {
292	    String methodName = method.getSimpleName().toString();
293	
294	    MethodSpec.Builder builder = MethodSpec.methodBuilder(methodName).addAnnotation(Override.class);
295	
296	    Set<Modifier> modifiers = method.getModifiers();
297	    modifiers = new LinkedHashSet<>(modifiers);
298	    modifiers.remove(Modifier.ABSTRACT);
299	    Modifier defaultModifier = null;
300	    // Modifier.DEFAULT doesn't exist until Java 8.
301	    try {
302	      defaultModifier = Modifier.valueOf("DEFAULT");
303	    } catch (IllegalArgumentException e) {
304	      // Ignored.
305	    }
306	    modifiers.remove(defaultModifier);
307	
308	    builder = builder.addModifiers(modifiers);
309	
310	    for (TypeParameterElement typeParameterElement : method.getTypeParameters()) {
311	      TypeVariable var = (TypeVariable) typeParameterElement.asType();
312	      builder = builder.addTypeVariable(TypeVariableName.get(var));
313	    }
314	
315	    builder =
316	        builder
317	            .returns(TypeName.get(method.getReturnType()))
318	            .addParameters(getParameters(method))
319	            .varargs(method.isVarArgs());
320	
321	    for (TypeMirror thrownType : method.getThrownTypes()) {
322	      builder = builder.addException(TypeName.get(thrownType));
323	    }
324	
325	    return builder;
326	  }
