332	  List<ParameterSpec> getParameters(List<? extends VariableElement> parameters) {
333	    List<ParameterSpec> result = new ArrayList<>();
334	    for (VariableElement parameter : parameters) {
335	      result.add(getParameter(parameter));
336	    }
337	    return dedupedParameters(result);
338	  }
