340	  private static List<ParameterSpec> dedupedParameters(List<ParameterSpec> parameters) {
341	    boolean hasDupes = false;
342	    Set<String> names = new HashSet<>();
343	    for (ParameterSpec parameter : parameters) {
344	      String name = parameter.name;
345	      if (names.contains(name)) {
346	        hasDupes = true;
347	      } else {
348	        names.add(name);
349	      }
350	    }
351	
352	    if (hasDupes) {
353	      List<ParameterSpec> copy = parameters;
354	      parameters = new ArrayList<>();
355	      for (int i = 0; i < copy.size(); i++) {
356	        ParameterSpec parameter = copy.get(i);
357	        parameters.add(
358	            ParameterSpec.builder(parameter.type, parameter.name + i)
359	                .addModifiers(parameter.modifiers)
360	                .addAnnotations(parameter.annotations)
361	                .build());
362	      }
363	    }
364	
365	    return parameters;
366	  }
