368	  private ParameterSpec getParameter(VariableElement parameter) {
369	    TypeName type = TypeName.get(parameter.asType());
370	    return ParameterSpec.builder(type, computeParameterName(parameter, type))
371	        .addModifiers(parameter.getModifiers())
372	        .addAnnotations(getAnnotations(parameter))
373	        .build();
374	  }
