376	  private static String computeParameterName(VariableElement parameter, TypeName type) {
377	    String rawClassName = type.withoutAnnotations().toString();
378	
379	    String name;
380	
381	    if (type.isPrimitive() || type.isBoxedPrimitive()) {
382	      name = getSmartPrimitiveParameterName(parameter);
383	    } else {
384	      if (rawClassName.contains("<") && rawClassName.contains(">")) {
385	        String[] preGenericSplit = rawClassName.split("<");
386	        String preGeneric = preGenericSplit[0];
387	        String[] postGenericSplit = rawClassName.split(">");
388	        String postGeneric = postGenericSplit[postGenericSplit.length - 1];
389	        if (postGenericSplit.length > 1) {
390	          rawClassName = preGeneric + postGeneric;
391	        } else {
392	          rawClassName = preGeneric;
393	        }
394	      }
395	
396	      String[] qualifiers = rawClassName.split("\\.");
397	      rawClassName = qualifiers[qualifiers.length - 1];
398	
399	      rawClassName = applySmartParameterNameReplacements(rawClassName);
400	
401	      boolean allCaps = true;
402	      for (char c : rawClassName.toCharArray()) {
403	        if (Character.isLowerCase(c)) {
404	          allCaps = false;
405	          break;
406	        }
407	      }
408	      if (allCaps) {
409	        name = rawClassName.toLowerCase(Locale.ROOT);
410	      } else {
411	        int indexOfLastWordStart = 0;
412	        char[] chars = rawClassName.toCharArray();
413	        for (int i = 0, charArrayLength = chars.length; i < charArrayLength; i++) {
414	          char c = chars[i];
415	          if (Character.isUpperCase(c)) {
416	            indexOfLastWordStart = i;
417	          }
418	        }
419	        rawClassName = rawClassName.substring(indexOfLastWordStart, rawClassName.length());
420	
421	        name =
422	            Character.toLowerCase(rawClassName.charAt(0))
423	                + rawClassName.substring(1, rawClassName.length());
424	      }
425	    }
426	
427	    return name;
428	  }
