430	  private static String getSmartPrimitiveParameterName(VariableElement parameter) {
431	    for (AnnotationMirror annotation : parameter.getAnnotationMirrors()) {
432	      String annotationName = annotation.getAnnotationType().toString().toUpperCase(Locale.ROOT);
433	      if (annotationName.endsWith("RES")) {
434	        // Catch annotations like StringRes
435	        return "id";
436	      } else if (annotationName.endsWith("RANGE")) {
437	        // Catch annotations like IntRange
438	        return "value";
439	      }
440	    }
441	
442	    return parameter.getSimpleName().toString();
443	  }
