445	  private static String applySmartParameterNameReplacements(String name) {
446	    name = name.replace("[]", "s");
447	    name = name.replace(Class.class.getSimpleName(), "clazz");
448	    name = name.replace(Object.class.getSimpleName(), "o");
449	    return name;
450	  }
