452	  private List<AnnotationSpec> getAnnotations(VariableElement element) {
453	    List<AnnotationSpec> result = new ArrayList<>();
454	    for (AnnotationMirror mirror : element.getAnnotationMirrors()) {
455	      result.add(maybeConvertSupportLibraryAnnotation(mirror));
456	    }
457	    return result;
