460	  private AnnotationSpec maybeConvertSupportLibraryAnnotation(AnnotationMirror mirror) {
461	    String annotationName = mirror.getAnnotationType().asElement().toString();
462	    boolean preferAndroidX = visibleForTesting().equals(ANDROIDX_VISIBLE_FOR_TESTING);
463	    ImmutableBiMap<ClassName, ClassName> map =
464	        ImmutableBiMap.<ClassName, ClassName>builder()
465	            .put(SUPPORT_NONNULL_ANNOTATION, ANDROIDX_NONNULL_ANNOTATION)
466	            .put(SUPPORT_CHECK_RESULT_ANNOTATION, ANDROIDX_CHECK_RESULT_ANNOTATION)
467	            .put(SUPPORT_VISIBLE_FOR_TESTING, ANDROIDX_VISIBLE_FOR_TESTING)
468	            .build();
469	
470	    ClassName remapped = null;
471	    if (preferAndroidX && annotationName.startsWith("android.support.annotation")) {
472	      remapped = ClassName.get((TypeElement) mirror.getAnnotationType().asElement());
473	    } else if (!preferAndroidX && annotationName.startsWith("androidx.annotation")) {
474	      remapped = ClassName.get((TypeElement) mirror.getAnnotationType().asElement());
475	    }
476	    if (remapped != null && map.containsKey(remapped)) {
477	      return AnnotationSpec.builder(map.get(remapped)).build();
478	    } else {
479	      return AnnotationSpec.get(mirror);
480	    }
481	  }
