599	  private final class FilterPublicMethods implements Predicate<Element> {
600	    @Nullable private final TypeMirror returnType;
601	    private final MethodType methodType;
602	
603	    FilterPublicMethods(@Nullable TypeMirror returnType, MethodType methodType) {
604	      this.returnType = returnType;
605	      this.methodType = methodType;
606	    }
607	
608	    FilterPublicMethods(@Nullable TypeElement returnType, MethodType methodType) {
609	      this(returnType != null ? returnType.asType() : null, methodType);
610	    }
611	
612	    @Override
613	    public boolean apply(@Nullable Element input) {
614	      if (input == null
615	          || input.getKind() != ElementKind.METHOD
616	          || !input.getModifiers().contains(Modifier.PUBLIC)) {
617	        return false;
618	      }
619	      boolean isStatic = input.getModifiers().contains(Modifier.STATIC);
620	      if (methodType == MethodType.STATIC && !isStatic) {
621	        return false;
622	      } else if (methodType == MethodType.INSTANCE && isStatic) {
623	        return false;
624	      }
625	      ExecutableElement method = (ExecutableElement) input;
626	      return returnType == null || isReturnValueTypeMatching(method, returnType);
627	    }
628	  }
629	
630	  boolean isReturnValueTypeMatching(ExecutableElement method, TypeElement expectedReturnType) {
631	    return isReturnValueTypeMatching(method, expectedReturnType.asType());
632	  }
633	
634	  private boolean isReturnValueTypeMatching(
635	      ExecutableElement method, TypeMirror expectedReturnType) {
636	    return processingEnv.getTypeUtils().isAssignable(method.getReturnType(), expectedReturnType);
637	  }
638	
639	  private static final class ToMethod implements Function<Element, ExecutableElement> {
640	
641	    @Nullable
642	    @Override
643	    public ExecutableElement apply(@Nullable Element input) {
644	      return (ExecutableElement) input;
645	    }
646	  }
647	}
