36	 * runtime.
37	 *
38	 * <p>The generated class looks something like this:
39	 *
40	 * <pre>
41	 * <code>
42	 *  final class GeneratedAppGlideModuleImpl extends com.bumptech.glide.GeneratedAppGlideModule {
43	 *    private final com.bumptech.glide.samples.giphy.GiphyGlideModule appGlideModule;
44	 *
