49	 *            + " com.bumptech.glide.samples.giphy.GiphyGlideModule");
50	 *        android.util.Log.d("Glide", "Discovered LibraryGlideModule from annotation:"
51	 *            + "com.bumptech.glide.integration.okhttp3.OkHttpLibraryGlideModule");
52	 *      }
53	 *    }
54	 *
55	 *    {@literal @java.lang.Override}
56	 *    public void applyOptions(android.content.Context context,
57	 *        com.bumptech.glide.GlideBuilder builder) {
58	 *      appGlideModule.applyOptions(context, builder);
59	 *    }
60	 *
61	 *    {@literal @java.lang.Override}
62	 *    public void registerComponents(android.content.Context context,
63	 *        com.bumptech.glide.Registry registry) {
