97	  TypeSpec generate(TypeElement appGlideModule, Set<String> libraryGlideModuleClassNames) {
98	    ClassName appGlideModuleClassName = ClassName.get(appGlideModule);
99	    List<String> excludedGlideModuleClassNames = getExcludedGlideModuleClassNames(appGlideModule);
100	
101	    List<String> orderedLibraryGlideModuleClassNames =
102	        new ArrayList<>(libraryGlideModuleClassNames);
103	    Collections.sort(orderedLibraryGlideModuleClassNames);
104	
105	    MethodSpec constructor =
106	        generateConstructor(
107	            appGlideModuleClassName,
108	            orderedLibraryGlideModuleClassNames,
109	            excludedGlideModuleClassNames);
110	
111	    MethodSpec registerComponents =
112	        generateRegisterComponents(
113	            orderedLibraryGlideModuleClassNames, excludedGlideModuleClassNames);
114	
115	    MethodSpec getExcludedModuleClasses =
116	        generateGetExcludedModuleClasses(excludedGlideModuleClassNames);
117	
118	    MethodSpec applyOptions =
119	        MethodSpec.methodBuilder("applyOptions")
120	            .addModifiers(Modifier.PUBLIC)
121	            .addAnnotation(Override.class)
122	            .addParameter(
123	                ParameterSpec.builder(ClassName.get("android.content", "Context"), "context")
124	                    .addAnnotation(processorUtil.nonNull())
125	                    .build())
126	            .addParameter(
127	                ParameterSpec.builder(
128	                        ClassName.get("com.bumptech.glide", "GlideBuilder"), "builder")
129	                    .addAnnotation(processorUtil.nonNull())
130	                    .build())
131	            .addStatement("appGlideModule.applyOptions(context, builder)", appGlideModule)
132	            .build();
133	
134	    MethodSpec isManifestParsingEnabled =
135	        MethodSpec.methodBuilder("isManifestParsingEnabled")
136	            .addModifiers(Modifier.PUBLIC)
137	            .addAnnotation(Override.class)
138	            .returns(boolean.class)
139	            .addStatement("return appGlideModule.isManifestParsingEnabled()", appGlideModule)
140	            .build();
