146	                AnnotationSpec.builder(SuppressWarnings.class)
147	                    .addMember("value", "$S", "deprecation")
148	                    .build())
149	            .superclass(
150	                ClassName.get(
151	                    GENERATED_ROOT_MODULE_PACKAGE_NAME, GENERATED_ROOT_MODULE_SIMPLE_NAME))
152	            .addField(appGlideModuleClassName, "appGlideModule", Modifier.PRIVATE, Modifier.FINAL)
153	            .addMethod(constructor)
154	            .addMethod(applyOptions)
155	            .addMethod(registerComponents)
156	            .addMethod(isManifestParsingEnabled)
