174	  // TODO: When we drop support for parsing GlideModules from AndroidManifests, remove this method.
175	  private MethodSpec generateGetExcludedModuleClasses(Collection<String> excludedClassNames) {
176	    TypeName wildCardOfObject = WildcardTypeName.subtypeOf(Object.class);
177	    ParameterizedTypeName classOfWildcardOfObjet =
178	        ParameterizedTypeName.get(ClassName.get(Class.class), wildCardOfObject);
179	    ParameterizedTypeName setOfClassOfWildcardOfObject =
180	        ParameterizedTypeName.get(ClassName.get(Set.class), classOfWildcardOfObjet);
181	    ParameterizedTypeName hashSetOfClassOfWildcardOfObject =
182	        ParameterizedTypeName.get(ClassName.get(HashSet.class), classOfWildcardOfObjet);
183	    MethodSpec.Builder builder =
184	        MethodSpec.methodBuilder("getExcludedModuleClasses")
185	            .addModifiers(Modifier.PUBLIC)
186	            .addAnnotation(Override.class)
187	            .addAnnotation(processorUtil.nonNull())
188	            .returns(setOfClassOfWildcardOfObject);
189	
190	    if (excludedClassNames.isEmpty()) {
191	      builder.addStatement("return $T.emptySet()", Collections.class);
192	    } else {
193	      builder.addStatement(
194	          "$T excludedClasses = new $T()",
195	          setOfClassOfWildcardOfObject,
196	          hashSetOfClassOfWildcardOfObject);
197	      for (String excludedClassName : excludedClassNames) {
198	        // TODO: Remove this when we no longer support manifest parsing.
199	        // Using a Literal ($L) instead of a type ($T) to get a fully qualified import that allows
200	        // us to suppress deprecation warnings. Aimed at deprecated GlideModules.
201	        builder.addStatement("excludedClasses.add($L.class)", excludedClassName);
202	      }
203	      builder.addStatement("return excludedClasses");
204	    }
205	
206	    return builder.build();
207	  }
