209	  private MethodSpec generateRegisterComponents(
210	      Collection<String> libraryGlideModuleClassNames,
211	      Collection<String> excludedGlideModuleClassNames) {
212	    MethodSpec.Builder registerComponents =
213	        MethodSpec.methodBuilder("registerComponents")
214	            .addModifiers(Modifier.PUBLIC)
215	            .addAnnotation(Override.class)
216	            .addParameter(
217	                ParameterSpec.builder(ClassName.get("android.content", "Context"), "context")
218	                    .addAnnotation(processorUtil.nonNull())
219	                    .build())
220	            .addParameter(
221	                ParameterSpec.builder(ClassName.get("com.bumptech.glide", "Glide"), "glide")
222	                    .addAnnotation(processorUtil.nonNull())
223	                    .build())
224	            .addParameter(
225	                ParameterSpec.builder(ClassName.get("com.bumptech.glide", "Registry"), "registry")
226	                    .addAnnotation(processorUtil.nonNull())
227	                    .build());
228	
229	    for (String glideModule : libraryGlideModuleClassNames) {
230	      if (excludedGlideModuleClassNames.contains(glideModule)) {
231	        continue;
232	      }
233	      ClassName moduleClassName = ClassName.bestGuess(glideModule);
234	      registerComponents.addStatement(
235	          "new $T().registerComponents(context, glide, registry)", moduleClassName);
236	    }
237	    // Order matters here. The AppGlideModule must be called last.
238	    registerComponents.addStatement("appGlideModule.registerComponents(context, glide, registry)");
239	    return registerComponents.build();
240	  }
