242	  private boolean doesAppGlideModuleConstructorAcceptContext(ClassName appGlideModule) {
243	    TypeElement appGlideModuleType =
244	        processingEnv.getElementUtils().getTypeElement(appGlideModule.reflectionName());
245	
246	    for (Element enclosed : appGlideModuleType.getEnclosedElements()) {
247	      if (enclosed.getKind() == ElementKind.CONSTRUCTOR) {
248	        ExecutableElement constructor = (ExecutableElement) enclosed;
249	        List<? extends VariableElement> parameters = constructor.getParameters();
250	        if (parameters.isEmpty()) {
251	          return false;
252	        } else if (parameters.size() > 1) {
253	          throw new IllegalStateException(
254	              "Constructor for "
255	                  + appGlideModule
256	                  + " accepts too many parameters"
257	                  + ", it should accept no parameters, or a single Context");
258	        } else {
259	          VariableElement parameter = parameters.get(0);
260	          TypeMirror parameterType = parameter.asType();
261	          TypeMirror contextType =
262	              processingEnv.getElementUtils().getTypeElement("android.content.Context").asType();
263	          if (!processingEnv.getTypeUtils().isSameType(parameterType, contextType)) {
264	            throw new IllegalStateException("Unrecognized type: " + parameterType);
265	          }
266	          return true;
267	        }
268	      }
269	    }
270	    return false;
271	  }
272	
273	  private MethodSpec generateConstructor(
274	      ClassName appGlideModule,
275	      Collection<String> libraryGlideModuleClassNames,
276	      Collection<String> excludedGlideModuleClassNames) {
277	    MethodSpec.Builder constructorBuilder =
278	        MethodSpec.constructorBuilder()
279	            .addModifiers(Modifier.PUBLIC)
280	            .addParameter(
281	                ParameterSpec.builder(ClassName.get("android.content", "Context"), "context")
282	                    .build());
283	
284	    if (doesAppGlideModuleConstructorAcceptContext(appGlideModule)) {
285	      constructorBuilder.addStatement("appGlideModule = new $T(context)", appGlideModule);
286	    } else {
287	      constructorBuilder.addStatement("appGlideModule = new $T()", appGlideModule);
288	    }
289	
290	    ClassName androidLogName = ClassName.get("android.util", "Log");
291	
292	    // Add some log lines to indicate to developers which modules where discovered.
293	    constructorBuilder.beginControlFlow(
294	        "if ($T.isLoggable($S, $T.DEBUG))", androidLogName, GLIDE_LOG_TAG, androidLogName);
295	    constructorBuilder.addStatement(
296	        "$T.d($S, $S)",
297	        androidLogName,
298	        GLIDE_LOG_TAG,
299	        "Discovered AppGlideModule from annotation: " + appGlideModule);
300	    // Excluded GlideModule classes from the manifest are logged in Glide's singleton.
301	    for (String glideModule : libraryGlideModuleClassNames) {
302	      if (excludedGlideModuleClassNames.contains(glideModule)) {
303	        constructorBuilder.addStatement(
304	            "$T.d($S, $S)",
305	            androidLogName,
306	            GLIDE_LOG_TAG,
307	            "AppGlideModule excludes LibraryGlideModule from annotation: " + glideModule);
308	      } else {
309	        constructorBuilder.addStatement(
310	            "$T.d($S, $S)",
311	            androidLogName,
312	            GLIDE_LOG_TAG,
313	            "Discovered LibraryGlideModule from annotation: " + glideModule);
314	      }
315	    }
316	    constructorBuilder.endControlFlow();
317	    return constructorBuilder.build();
318	  }
319	
320	  private List<String> getExcludedGlideModuleClassNames(TypeElement appGlideModule) {
321	    Set<String> names =
322	        processorUtil.findClassValuesFromAnnotationOnClassAsNames(appGlideModule, Excludes.class);
323	    List<String> result = new ArrayList<>(names);
324	    Collections.sort(result);
325	    return result;
326	  }
