111	                new Function<MethodSpec, MethodAndStaticVar>() {
112	                  @Override
113	                  public MethodAndStaticVar apply(MethodSpec input) {
114	                    return new MethodAndStaticVar(input);
115	                  }
116	                })
117	            .toList();
