220	      staticMethods.add(generateStaticMethodEquivalentForRequestOptionsStaticMethod(element));
221	    }
222	    return staticMethods;
223	  }
224	
225	  /**
226	   * This method is a bit of a hack, but it lets us tie the static version of a method with the
227	   * instance version. In turn that lets us call the instance versions on the generated subclass,
228	   * instead of just delegating to the RequestOptions static methods. Using the instance methods on
229	   * the generated subclass allows our static methods to properly call code that overrides an
230	   * existing method in RequestOptions.
231	   *
232	   * <p>The string names here just map between the static methods in {@code
233	   * com.bumptech.glide.request.RequestOptions} and the instance methods they call.
234	   */
235	  private static String getInstanceMethodNameFromStaticMethodName(String staticMethodName) {
236	    String equivalentInstanceMethodName;
237	    if ("bitmapTransform".equals(staticMethodName)) {
238	      equivalentInstanceMethodName = "transform";
239	    } else if ("decodeTypeOf".equals(staticMethodName)) {
240	      equivalentInstanceMethodName = "decode";
241	    } else if (staticMethodName.endsWith("Transform")) {
242	      equivalentInstanceMethodName = staticMethodName.substring(0, staticMethodName.length() - 9);
243	    } else if (staticMethodName.endsWith("Of")) {
244	      equivalentInstanceMethodName = staticMethodName.substring(0, staticMethodName.length() - 2);
245	    } else if ("noTransformation".equals(staticMethodName)) {
246	      equivalentInstanceMethodName = "dontTransform";
247	    } else if ("noAnimation".equals(staticMethodName)) {
248	      equivalentInstanceMethodName = "dontAnimate";
249	    } else if (staticMethodName.equals("option")) {
250	      equivalentInstanceMethodName = "set";
251	    } else {
252	      throw new IllegalArgumentException("Unrecognized static method name: " + staticMethodName);
253	    }
254	    return equivalentInstanceMethodName;
255	  }
256	
257	  private MethodAndStaticVar generateStaticMethodEquivalentForRequestOptionsStaticMethod(
258	      ExecutableElement staticMethod) {
259	    boolean memoize = memoizeStaticMethodFromArguments(staticMethod);
260	    String staticMethodName = staticMethod.getSimpleName().toString();
261	
262	    String equivalentInstanceMethodName =
263	        getInstanceMethodNameFromStaticMethodName(staticMethodName);
264	
265	    MethodSpec.Builder methodSpecBuilder =
266	        MethodSpec.methodBuilder(staticMethodName)
267	            .addModifiers(Modifier.PUBLIC, Modifier.STATIC)
268	            .addJavadoc(processorUtil.generateSeeMethodJavadoc(staticMethod))
269	            .returns(glideOptionsName);
270	
271	    StringBuilder createNewOptionAndCall =
272	        createNewOptionAndCall(
273	            memoize, methodSpecBuilder, "new $T().$N(", processorUtil.getParameters(staticMethod));
274	
275	    FieldSpec requiredStaticField = null;
276	    if (memoize) {
277	      // Generates code that looks like:
278	      // if (GlideOptions.<methodName> == null) {
279	      //   GlideOptions.<methodName> = new GlideOptions().<methodName>().autoClone()
280	      // }
281	
282	      // Mix in an incrementing unique id to handle method overloading.
283	      String staticVariableName = staticMethodName + nextFieldId++;
284	      requiredStaticField =
285	          FieldSpec.builder(glideOptionsName, staticVariableName)
286	              .addModifiers(Modifier.PRIVATE, Modifier.STATIC)
287	              .build();
288	      methodSpecBuilder
289	          .beginControlFlow("if ($T.$N == null)", glideOptionsName, staticVariableName)
290	          .addStatement(
291	              "$T.$N =\n" + createNewOptionAndCall + ".$N",
292	              glideOptionsName,
293	              staticVariableName,
294	              glideOptionsName,
295	              equivalentInstanceMethodName,
296	              "autoClone()")
297	          .endControlFlow()
298	          .addStatement("return $T.$N", glideOptionsName, staticVariableName);
299	    } else {
300	      // Generates code that looks like:
301	      // return new GlideOptions().<methodName>()
302	      methodSpecBuilder.addStatement(
303	          "return " + createNewOptionAndCall, glideOptionsName, equivalentInstanceMethodName);
304	    }
305	
306	    List<? extends TypeParameterElement> typeParameters = staticMethod.getTypeParameters();
307	    for (TypeParameterElement typeParameterElement : typeParameters) {
308	      methodSpecBuilder.addTypeVariable(
309	          TypeVariableName.get(typeParameterElement.getSimpleName().toString()));
310	    }
311	
312	    methodSpecBuilder
313	        .addAnnotation(processorUtil.checkResult())
314	        .addAnnotation(processorUtil.nonNull());
315	
316	    return new MethodAndStaticVar(methodSpecBuilder.build(), requiredStaticField);
317	  }
318	
319	  @SuppressWarnings("checkstyle:UnnecessaryParentheses") // Readability
320	  private static boolean memoizeStaticMethodFromArguments(ExecutableElement staticMethod) {
321	    return staticMethod.getParameters().isEmpty()
322	        || (staticMethod.getParameters().size() == 1
323	            && staticMethod
324	                .getParameters()
325	                .get(0)
326	                .getSimpleName()
327	                .toString()
328	                .equals("android.content.Context"));
329	  }
330	
331	  private StringBuilder createNewOptionAndCall(
332	      boolean memoize,
333	      MethodSpec.Builder methodSpecBuilder,
334	      String start,
335	      List<ParameterSpec> specs) {
336	    StringBuilder createNewOptionAndCall = new StringBuilder(start);
337	    if (!specs.isEmpty()) {
338	      methodSpecBuilder.addParameters(specs);
339	      for (ParameterSpec parameter : specs) {
340	        createNewOptionAndCall.append(parameter.name);
341	        // use the Application Context to avoid memory leaks.
342	        if (memoize && isAndroidContext(parameter)) {
343	          createNewOptionAndCall.append(".getApplicationContext()");
344	        }
345	        createNewOptionAndCall.append(", ");
346	      }
347	      createNewOptionAndCall =
348	          new StringBuilder(
349	              createNewOptionAndCall.substring(0, createNewOptionAndCall.length() - 2));
350	    }
351	    createNewOptionAndCall.append(")");
352	    return createNewOptionAndCall;
353	  }
354	
355	  private boolean isAndroidContext(ParameterSpec parameter) {
356	    return parameter.type.toString().equals("android.content.Context");
357	  }
358	
359	  private MethodAndStaticVar generateStaticMethodEquivalentForExtensionMethod(
360	      ExecutableElement instanceMethod) {
361	    String staticMethodName = getStaticMethodName(instanceMethod);
362	    String instanceMethodName = instanceMethod.getSimpleName().toString();
363	    if (Strings.isNullOrEmpty(staticMethodName)) {
364	      if (instanceMethodName.startsWith("dont")) {
365	        staticMethodName = "no" + instanceMethodName.replace("dont", "");
366	      } else {
367	        staticMethodName = instanceMethodName + "Of";
368	      }
369	    }
370	    boolean memoize = memoizeStaticMethodFromAnnotation(instanceMethod);
371	
372	    //noinspection ResultOfMethodCallIgnored
373	    Preconditions.checkNotNull(staticMethodName);
374	    MethodSpec.Builder methodSpecBuilder =
375	        MethodSpec.methodBuilder(staticMethodName)
376	            .addModifiers(Modifier.PUBLIC, Modifier.STATIC)
377	            .addJavadoc(processorUtil.generateSeeMethodJavadoc(instanceMethod))
378	            .varargs(instanceMethod.isVarArgs())
379	            .returns(glideOptionsName);
380	
381	    List<? extends VariableElement> parameters = instanceMethod.getParameters();
382	
383	    // Always remove the first parameter because it's always RequestOptions in extensions. The
384	    // actual method we want to generate will pass the RequestOptions in to the extension method,
385	    // but should not itself require a RequestOptions object to be passed in.
386	    if (parameters.isEmpty()) {
387	      throw new IllegalArgumentException("Expected non-empty parameters for: " + instanceMethod);
388	    }
389	    // Remove is not supported.
390	    parameters = parameters.subList(1, parameters.size());
391	
392	    StringBuilder createNewOptionAndCall =
393	        createNewOptionAndCall(
394	            memoize, methodSpecBuilder, "new $T().$L(", processorUtil.getParameters(parameters));
395	
396	    FieldSpec requiredStaticField = null;
397	    if (memoize) {
398	      // Generates code that looks like:
399	      // if (GlideOptions.<methodName> == null) {
400	      //   GlideOptions.<methodName> = new GlideOptions().<methodName>().autoClone()
401	      // }
402	
403	      // Mix in an incrementing unique id to handle method overloading.
404	      String staticVariableName = staticMethodName + nextFieldId++;
405	      requiredStaticField =
406	          FieldSpec.builder(glideOptionsName, staticVariableName)
407	              .addModifiers(Modifier.PRIVATE, Modifier.STATIC)
408	              .build();
409	      methodSpecBuilder
410	          .beginControlFlow("if ($T.$N == null)", glideOptionsName, staticVariableName)
411	          .addStatement(
412	              "$T.$N =\n" + createNewOptionAndCall + ".$N",
413	              glideOptionsName,
414	              staticVariableName,
415	              glideOptionsName,
416	              instanceMethodName,
417	              "autoClone()")
418	          .endControlFlow()
419	          .addStatement("return $T.$N", glideOptionsName, staticVariableName);
420	    } else {
421	      // Generates code that looks like:
422	      // return new GlideOptions().<methodName>()
423	      methodSpecBuilder.addStatement(
424	          "return " + createNewOptionAndCall, glideOptionsName, instanceMethodName);
425	    }
426	
427	    List<? extends TypeParameterElement> typeParameters = instanceMethod.getTypeParameters();
428	    for (TypeParameterElement typeParameterElement : typeParameters) {
429	      methodSpecBuilder.addTypeVariable(
430	          TypeVariableName.get(typeParameterElement.getSimpleName().toString()));
431	    }
432	
433	    methodSpecBuilder.addAnnotation(processorUtil.checkResult());
434	
435	    return new MethodAndStaticVar(methodSpecBuilder.build(), requiredStaticField);
436	  }
437	
438	  @Nullable
439	  private static String getStaticMethodName(ExecutableElement element) {
440	    GlideOption glideOption = element.getAnnotation(GlideOption.class);
441	    String result = glideOption != null ? glideOption.staticMethodName() : null;
442	    return Strings.emptyToNull(result);
443	  }
444	
445	  private static boolean memoizeStaticMethodFromAnnotation(ExecutableElement element) {
446	    GlideOption glideOption = element.getAnnotation(GlideOption.class);
447	    return glideOption != null && glideOption.memoizeStaticMethod();
448	  }
449	
450	  private static boolean skipStaticMethod(ExecutableElement element) {
451	    GlideOption glideOption = element.getAnnotation(GlideOption.class);
452	    return glideOption != null && glideOption.skipStaticMethod();
453	  }
454	
455	  private static final class MethodAndStaticVar {
456	    @Nullable final MethodSpec method;
457	    @Nullable final FieldSpec staticField;
458	
459	    MethodAndStaticVar(@Nullable MethodSpec method) {
460	      this(method, null /*staticField*/);
461	    }
462	
463	    MethodAndStaticVar(@Nullable MethodSpec method, @Nullable FieldSpec staticField) {
464	      this.method = method;
465	      this.staticField = staticField;
466	    }
467	  }
468	
469	  private static final class MethodSignature {
470	    private final TypeName returnType;
471	    private final List<TypeName> parameterTypes;
472	    private final boolean isStatic;
473	    private final String name;
474	
475	    MethodSignature(MethodSpec spec) {
476	      name = spec.name;
477	      isStatic = spec.modifiers.contains(Modifier.STATIC);
478	      returnType = spec.returnType;
479	      parameterTypes =
480	          Lists.transform(
481	              spec.parameters,
482	              new Function<ParameterSpec, TypeName>() {
483	                @Nullable
484	                @Override
485	                public TypeName apply(ParameterSpec parameterSpec) {
486	                  return parameterSpec.type;
487	                }
488	              });
489	    }
490	
491	    @Override
492	    public boolean equals(Object o) {
493	      if (o instanceof MethodSignature) {
494	        MethodSignature other = (MethodSignature) o;
495	        return name.equals(other.name)
496	            && returnType.equals(other.returnType)
497	            && parameterTypes.equals(other.parameterTypes)
498	            && isStatic == other.isStatic;
499	      }
500	      return false;
501	    }
502	
503	    @Override
504	    public int hashCode() {
505	      return Objects.hashCode(name, returnType, parameterTypes, isStatic);
506	    }
507	  }
508	}
