27	/**
28	 * Validates that classes annotated with {@link com.bumptech.glide.annotation.GlideExtension}
29	 * contains methods with the expected format.
30	 *
31	 * <p>Validation is performed so that errors can be found when a library is compiled. Without
32	 * validation, an error written in to a library wouldn't be found until Glide tried to generate code
33	 * for an Application.
34	 */
35	final class GlideExtensionValidator {
36	  private final ProcessingEnvironment processingEnvironment;
37	  private final ProcessorUtil processorUtil;
38	  private final boolean useLegacyTypeComparison;
39	
40	  GlideExtensionValidator(
41	      ProcessingEnvironment processingEnvironment,
42	      ProcessorUtil processorUtil,
43	      boolean useLegacyTypeComparison) {
44	    this.processingEnvironment = processingEnvironment;
45	    this.processorUtil = processorUtil;
46	    this.useLegacyTypeComparison = useLegacyTypeComparison;
47	  }
48	
49	  void validateExtension(TypeElement typeElement) {
50	    if (!typeElement.getModifiers().contains(Modifier.PUBLIC)) {
51	      throw new IllegalArgumentException(
52	          "RequestOptionsExtensions must be public, including: " + getName(typeElement));
53	    }
54	    for (Element element : typeElement.getEnclosedElements()) {
55	      if (element.getKind() == ElementKind.CONSTRUCTOR) {
56	        validateExtensionConstructor(element);
57	      } else if (element.getKind() == ElementKind.METHOD) {
58	        ExecutableElement executableElement = (ExecutableElement) element;
59	        if (executableElement.getAnnotation(GlideOption.class) != null) {
60	          validateGlideOption(executableElement);
61	        } else if (executableElement.getAnnotation(GlideType.class) != null) {
62	          validateGlideType(executableElement);
63	        }
64	      }
65	    }
66	  }
67	
68	  private static String getQualifiedMethodName(ExecutableElement executableElement) {
69	    return getEnclosingClassName(executableElement) + "#" + getName(executableElement);
70	  }
71	
72	  private static String getEnclosingClassName(Element element) {
73	    return element.getEnclosingElement().toString();
74	  }
75	
76	  private static String getName(Element element) {
77	    return element.toString();
78	  }
79	
80	  private static void validateExtensionConstructor(Element element) {
81	    if (!element.getModifiers().contains(Modifier.PRIVATE)) {
82	      throw new IllegalArgumentException(
83	          "RequestOptionsExtensions must be public, with private constructors and only static"
84	              + " methods. Found a non-private constructor in: "
85	              + getEnclosingClassName(element));
86	    }
87	    ExecutableElement executableElement = (ExecutableElement) element;
88	    if (!executableElement.getParameters().isEmpty()) {
89	      throw new IllegalArgumentException(
90	          "RequestOptionsExtensions must be public, with private constructors and only static"
91	              + " methods. Found parameters in the constructor of: "
92	              + getEnclosingClassName(element));
93	    }
94	  }
95	
96	  private void validateGlideOption(ExecutableElement executableElement) {
97	    validateGlideOptionAnnotations(executableElement);
98	    validateGlideOptionParameters(executableElement);
99	    TypeMirror returnType = executableElement.getReturnType();
100	    if (!isBaseRequestOptions(returnType)) {
101	      throw new IllegalArgumentException(
102	          "@GlideOption methods should return a"
103	              + " BaseRequestOptions<?> object, but "
104	              + getQualifiedMethodName(executableElement)
105	              + " returns "
106	              + returnType
107	              + ". If you're using old style @GlideOption methods, your"
108	              + " method may have a void return type, but doing so is deprecated and support will"
109	              + " be removed in a future version");
110	    }
111	    validateGlideOptionOverride(executableElement);
112	  }
113	
114	  private void validateGlideOptionAnnotations(ExecutableElement executableElement) {
115	    validateAnnotatedNonNull(executableElement);
116	  }
117	
118	  private void validateGlideOptionParameters(ExecutableElement executableElement) {
119	    if (executableElement.getParameters().isEmpty()) {
120	      throw new IllegalArgumentException(
121	          "@GlideOption methods must take a "
122	              + "BaseRequestOptions<?> object as their first parameter, but "
123	              + getQualifiedMethodName(executableElement)
124	              + " has none");
125	    }
126	    VariableElement first = executableElement.getParameters().get(0);
127	    TypeMirror expected = first.asType();
128	    if (!isBaseRequestOptions(expected)) {
129	      throw new IllegalArgumentException(
130	          "@GlideOption methods must take a"
131	              + " BaseRequestOptions<?> object as their first parameter, but the first parameter"
132	              + " in "
133	              + getQualifiedMethodName(executableElement)
134	              + " is "
135	              + expected);
136	    }
137	  }
138	
139	  private boolean isBaseRequestOptions(TypeMirror typeMirror) {
140	    if (useLegacyTypeComparison) {
141	      return typeMirror.toString().equals("com.bumptech.glide.request.BaseRequestOptions<?>");
142	    }
143	    return typeMirror instanceof DeclaredType declaredType
144	        && declaredType.asElement() instanceof TypeElement typeElement
145	        && typeElement
146	            .getQualifiedName()
147	            .contentEquals("com.bumptech.glide.request.BaseRequestOptions");
148	  }
149	
150	  private void validateGlideOptionOverride(ExecutableElement element) {
151	    int overrideType = processorUtil.getOverrideType(element);
152	    boolean isOverridingBaseRequestOptionsMethod = isMethodInBaseRequestOptions(element);
153	    if (isOverridingBaseRequestOptionsMethod && overrideType == GlideOption.OVERRIDE_NONE) {
154	      throw new IllegalArgumentException(
155	          "Accidentally attempting to override a method in"
156	              + " BaseRequestOptions. Add an 'override' value in the @GlideOption annotation"
157	              + " if this is intentional. Offending method: "
158	              + getQualifiedMethodName(element));
159	    } else if (!isOverridingBaseRequestOptionsMethod && overrideType != GlideOption.OVERRIDE_NONE) {
160	      throw new IllegalArgumentException(
161	          "Requested to override an existing method in"
162	              + " BaseRequestOptions, but no such method was found. Offending method: "
163	              + getQualifiedMethodName(element));
164	    }
165	  }
166	
167	  private boolean isMethodInBaseRequestOptions(ExecutableElement toFind) {
168	    // toFind is a method in a GlideExtension whose first argument is a BaseRequestOptions<?> type.
169	    // Since we're comparing against methods in BaseRequestOptions itself, we need to drop that
170	    // first type.
171	    TypeElement requestOptionsType =
172	        processingEnvironment
173	            .getElementUtils()
174	            .getTypeElement(RequestOptionsGenerator.BASE_REQUEST_OPTIONS_QUALIFIED_NAME);
175	    List<TypeMirror> toFindParameterTypes =
176	        getComparableParameterTypes(toFind, /* skipFirst= */ true);
177	    String toFindSimpleName = toFind.getSimpleName().toString();
178	    for (Element element : requestOptionsType.getEnclosedElements()) {
179	      if (element.getKind() != ElementKind.METHOD) {
180	        continue;
181	      }
182	      ExecutableElement inBase = (ExecutableElement) element;
183	      if (toFindSimpleName.equals(inBase.getSimpleName().toString())) {
184	        List<TypeMirror> parameterTypesInBase =
185	            getComparableParameterTypes(inBase, /* skipFirst= */ false);
186	        if (useLegacyTypeComparison) {
187	          List<String> stringsInBase = parameterTypesInBase.stream().map(Object::toString).toList();
188	          List<String> stringsToFind = toFindParameterTypes.stream().map(Object::toString).toList();
189	          if (stringsInBase.equals(stringsToFind)) {
190	            return true;
191	          }
192	        } else {
193	          if (isSameTypes(
194	              processingEnvironment.getTypeUtils(), parameterTypesInBase, toFindParameterTypes)) {
195	            return true;
196	          }
197	        }
198	      }
199	    }
200	    return false;
201	  }
202	
203	  private boolean isSameTypes(Types types, List<TypeMirror> a, List<TypeMirror> b) {
204	    if (a.size() != b.size()) {
205	      return false;
206	    }
207	    for (int i = 0; i < a.size(); i++) {
208	      if (!types.isSameType(a.get(i), b.get(i))) {
209	        return false;
210	      }
211	    }
212	    return true;
213	  }
214	
215	  private static List<TypeMirror> getComparableParameterTypes(
216	      ExecutableElement element, boolean skipFirst) {
217	    return element.getParameters().stream()
218	        .skip(skipFirst ? 1 : 0)
219	        .map(VariableElement::asType)
220	        .toList();
221	  }
222	
223	  private void validateGlideType(ExecutableElement executableElement) {
224	    TypeMirror returnType = executableElement.getReturnType();
225	    validateGlideTypeAnnotations(executableElement);
226	    if (!isRequestBuilder(returnType) || !typeMatchesExpected(returnType, executableElement)) {
227	      String expectedClassName = getGlideTypeValue(executableElement);
228	      throw new IllegalArgumentException(
229	          "@GlideType methods should return a RequestBuilder<"
230	              + expectedClassName
231	              + "> object, but "
232	              + getQualifiedMethodName(executableElement)
233	              + " returns: "
234	              + returnType
235	              + ". If you're using old style @GlideType methods, your"
236	              + " method may have a void return type, but doing so is deprecated and support will"
237	              + " be removed in a future version");
238	    }
239	    validateGlideTypeParameters(executableElement);
240	  }
241	
242	  private String getGlideTypeValue(ExecutableElement executableElement) {
243	    return processorUtil
244	        .findClassValuesFromAnnotationOnClassAsNames(executableElement, GlideType.class)
245	        .iterator()
246	        .next();
247	  }
248	
249	  private boolean typeMatchesExpected(TypeMirror returnType, ExecutableElement executableElement) {
250	    if (!(returnType instanceof DeclaredType declaredType)) {
251	      return false;
252	    }
253	    if (useLegacyTypeComparison) {
254	      List<? extends TypeMirror> typeArguments = declaredType.getTypeArguments();
255	      if (typeArguments.size() != 1) {
256	        return false;
257	      }
258	      TypeMirror argument = typeArguments.get(0);
259	      String expected = getGlideTypeValue(executableElement);
260	      return argument.toString().equals(expected);
261	    }
262	    Elements elements = processingEnvironment.getElementUtils();
263	    Types types = processingEnvironment.getTypeUtils();
264	    String glideTypeValue = getGlideTypeValue(executableElement);
265	    TypeElement glideTypeElement = elements.getTypeElement(glideTypeValue);
266	    if (glideTypeElement == null) {
267	      return false;
268	    }
269	    TypeElement requestBuilderElement =
270	        elements.getTypeElement("com.bumptech.glide.RequestBuilder");
271	    if (requestBuilderElement == null) {
272	      return false;
273	    }
274	    TypeMirror expectedType =
275	        types.getDeclaredType(requestBuilderElement, glideTypeElement.asType());
276	    return types.isSameType(returnType, expectedType);
277	  }
278	
279	  private boolean isRequestBuilder(TypeMirror typeMirror) {
280	    if (useLegacyTypeComparison) {
281	      TypeMirror toCompare = processingEnvironment.getTypeUtils().erasure(typeMirror);
282	      return toCompare.toString().equals("com.bumptech.glide.RequestBuilder");
283	    }
284	    Types types = processingEnvironment.getTypeUtils();
285	    Elements elements = processingEnvironment.getElementUtils();
286	    TypeMirror toCompare = types.erasure(typeMirror);
287	    return Objects.equals(
288	        types.asElement(toCompare), elements.getTypeElement("com.bumptech.glide.RequestBuilder"));
289	  }
290	
291	  private void validateGlideTypeParameters(ExecutableElement executableElement) {
292	    if (executableElement.getParameters().size() != 1) {
293	      throw new IllegalArgumentException(
294	          "@GlideType methods must take a"
295	              + " RequestBuilder object as their first and only parameter, but given multiple for: "
296	              + getQualifiedMethodName(executableElement));
297	    }
298	
299	    VariableElement first = executableElement.getParameters().get(0);
300	    TypeMirror argumentType = first.asType();
301	    if (useLegacyTypeComparison
302	        ? !argumentType.toString().startsWith("com.bumptech.glide.RequestBuilder")
303	        : !isRequestBuilder(argumentType)) {
304	      throw new IllegalArgumentException(
305	          "@GlideType methods must take a"
306	              + " RequestBuilder object as their first and only parameter, but given: "
307	              + argumentType
308	              + " for: "
309	              + getQualifiedMethodName(executableElement));
310	    }
311	  }
312	
313	  private void validateGlideTypeAnnotations(ExecutableElement executableElement) {
314	    validateAnnotatedNonNull(executableElement);
315	  }
316	
317	  private void validateAnnotatedNonNull(ExecutableElement executableElement) {
318	    Set<String> annotationNames =
319	        FluentIterable.from(executableElement.getAnnotationMirrors())
320	            .transform(
321	                new Function<AnnotationMirror, String>() {
322	                  @Override
323	                  public String apply(AnnotationMirror input) {
324	                    return input.getAnnotationType().asElement().toString();
325	                  }
326	                })
327	            .toSet();
328	    boolean noNonNull = true;
329	    for (ClassName nonNull : nonNulls()) {
330	      if (annotationNames.contains(nonNull.reflectionName())) {
331	        noNonNull = false;
332	        break;
333	      }
334	    }
335	    if (noNonNull) {
336	      processingEnvironment
337	          .getMessager()
338	          .printMessage(
339	              Kind.WARNING,
340	              getQualifiedMethodName(executableElement)
341	                  + " is missing the "
342	                  + processorUtil.nonNull().reflectionName()
343	                  + " annotation,"
344	                  + " please add it to ensure that your extension methods are always returning"
345	                  + " non-null values");
346	    }
347	  }
348	}
