132	  TypeSpec generate(
133	      String generatedCodePackageName,
134	      Set<String> glideExtensionClassNames,
135	      @Nullable TypeSpec generatedOptions) {
136	    if (generatedOptions != null) {
137	      requestOptionsClassName = ClassName.get(generatedCodePackageName, generatedOptions.name);
138	    } else {
139	      requestOptionsClassName =
140	          ClassName.get(
141	              RequestOptionsGenerator.REQUEST_OPTIONS_PACKAGE_NAME,
142	              RequestOptionsGenerator.BASE_REQUEST_OPTIONS_SIMPLE_NAME);
143	    }
144	
145	    generatedRequestBuilderClassName =
146	        ClassName.get(generatedCodePackageName, GENERATED_REQUEST_BUILDER_SIMPLE_NAME);
147	    generatedRequestBuilderOfTranscodeType =
148	        ParameterizedTypeName.get(generatedRequestBuilderClassName, transcodeTypeName);
149	    RequestOptionsExtensionGenerator requestOptionsExtensionGenerator =
150	        new RequestOptionsExtensionGenerator(generatedRequestBuilderOfTranscodeType, processorUtil);
151	
152	    ParameterizedTypeName requestBuilderOfTranscodeType =
153	        ParameterizedTypeName.get(
154	            ClassName.get(REQUEST_BUILDER_PACKAGE_NAME, REQUEST_BUILDER_SIMPLE_NAME),
