161	    return TypeSpec.classBuilder(GENERATED_REQUEST_BUILDER_SIMPLE_NAME)
162	        .addJavadoc(
163	            "Contains all public methods from {@link $T}, all options from\n", requestBuilderType)
164	        .addJavadoc("{@link $T} and all generated options from\n", requestOptionsType)
165	        .addJavadoc("{@link $T} in annotated methods in\n", GlideOption.class)
166	        .addJavadoc("{@link $T} annotated classes.\n", GlideExtension.class)
167	        .addJavadoc("\n")
168	        .addJavadoc("<p>Generated code, do not modify.\n")
169	        .addJavadoc("\n")
170	        .addJavadoc("@see $T\n", requestBuilderType)
171	        .addJavadoc("@see $T\n", requestOptionsType)
172	        .addAnnotation(
173	            AnnotationSpec.builder(SuppressWarnings.class)
