191	  /**
192	   * Generates methods with equivalent names and arguments to methods annotated with {@link
193	   * GlideOption} in {@link com.bumptech.glide.annotation.GlideExtension}s that return our generated
194	   * {@code com.bumptech.glide.RequestBuilder} subclass.
195	   */
196	  private List<MethodSpec> generateGeneratedRequestOptionsEquivalents(
197	      final List<MethodSpec> requestOptionsExtensionMethods,
198	      @Nullable final TypeSpec generatedOptions) {
199	    if (generatedOptions == null) {
200	      return Collections.emptyList();
201	    }
202	    return FluentIterable.from(generatedOptions.methodSpecs)
203	        .filter(
204	            new Predicate<MethodSpec>() {
205	              @Override
206	              public boolean apply(MethodSpec input) {
207	                return isUsefulGeneratedRequestOption(requestOptionsExtensionMethods, input);
208	              }
209	            })
210	        .transform(
211	            new Function<MethodSpec, MethodSpec>() {
212	              @Override
213	              public MethodSpec apply(MethodSpec input) {
