225	   * com.bumptech.glide.request.BaseRequestBuilder} subclass, so we only have to filter out methods
226	   * that override other methods to avoid duplicates.
227	   */
228	  private boolean isUsefulGeneratedRequestOption(
229	      List<MethodSpec> requestOptionsExtensionMethods, final MethodSpec requestOptionsMethod) {
230	    return !EXCLUDED_METHODS_FROM_BASE_REQUEST_OPTIONS.contains(requestOptionsMethod.name)
231	        && requestOptionsMethod.hasModifier(Modifier.PUBLIC)
232	        && !requestOptionsMethod.hasModifier(Modifier.STATIC)
233	        && requestOptionsMethod.returnType.toString().equals(requestOptionsClassName.toString())
234	        && !isExtensionMethod(requestOptionsExtensionMethods, requestOptionsMethod);
235	  }
