237	  private boolean isExtensionMethod(
238	      List<MethodSpec> requestOptionsExtensionMethods, final MethodSpec requestOptionsMethod) {
239	    return FluentIterable.from(requestOptionsExtensionMethods)
240	        .anyMatch(
241	            new Predicate<MethodSpec>() {
242	              @Override
243	              public boolean apply(MethodSpec input) {
244	                return input.name.equals(requestOptionsMethod.name)
245	                    && input.parameters.equals(requestOptionsMethod.parameters);
246	              }
247	            });
248	  }
