250	  /**
251	   * Generates a particular method with an equivalent name and arguments to the given method from
252	   * the generated {@code com.bumptech.glide.request.BaseRequestBuilder} subclass.
253	   */
254	  private MethodSpec generateGeneratedRequestOptionEquivalent(MethodSpec requestOptionMethod) {
255	    CodeBlock callRequestOptionsMethod =
256	        CodeBlock.builder()
257	            .add(".$N(", requestOptionMethod.name)
258	            .add(
259	                FluentIterable.from(requestOptionMethod.parameters)
260	                    .transform(
261	                        new Function<ParameterSpec, String>() {
262	                          @Override
263	                          public String apply(ParameterSpec input) {
264	                            return input.name;
265	                          }
266	                        })
267	                    .join(Joiner.on(", ")))
268	            .add(");\n")
269	            .build();
270	
271	    MethodSpec.Builder result =
272	        MethodSpec.methodBuilder(requestOptionMethod.name)
273	            .addJavadoc(
274	                processorUtil.generateSeeMethodJavadoc(
275	                    requestOptionsClassName, requestOptionMethod))
276	            .addModifiers(Modifier.PUBLIC)
277	            .varargs(requestOptionMethod.varargs)
278	            .addAnnotations(
279	                FluentIterable.from(requestOptionMethod.annotations)
280	                    .filter(
281	                        new Predicate<AnnotationSpec>() {
282	                          @Override
283	                          public boolean apply(AnnotationSpec input) {
284	                            return !input.type.equals(TypeName.get(Override.class))
285	                                // SafeVarargs can only be applied to final methods. GlideRequest is
286	                                // non-final to allow for mocking.
287	                                && !input.type.equals(TypeName.get(SafeVarargs.class))
288	                                // We need to combine warnings below.
289	                                && !input.type.equals(TypeName.get(SuppressWarnings.class));
290	                          }
291	                        })
292	                    .toList())
293	            .addTypeVariables(requestOptionMethod.typeVariables)
294	            .addParameters(requestOptionMethod.parameters)
295	            .returns(generatedRequestBuilderOfTranscodeType)
296	            .addCode("return ($T) super", generatedRequestBuilderOfTranscodeType)
297	            .addCode(callRequestOptionsMethod);
