306	  @Nullable
307	  private AnnotationSpec buildSuppressWarnings(MethodSpec requestOptionMethod) {
308	    Set<String> suppressions = new HashSet<>();
309	    if (requestOptionMethod.annotations.contains(
310	        AnnotationSpec.builder(SuppressWarnings.class).build())) {
311	      for (AnnotationSpec annotation : requestOptionMethod.annotations) {
312	        if (annotation.type.equals(TypeName.get(SuppressWarnings.class))) {
313	          List<CodeBlock> codeBlocks = annotation.members.get("value");
314	          suppressions.addAll(
315	              FluentIterable.from(codeBlocks)
316	                  .transform(
317	                      new Function<CodeBlock, String>() {
318	                        @Override
319	                        public String apply(CodeBlock input) {
320	                          return input.toString();
321	                        }
322	                      })
323	                  .toSet());
324	        }
325	      }
326	    }
327	
328	    if (requestOptionMethod.annotations.contains(
329	        AnnotationSpec.builder(SafeVarargs.class).build())) {
330	      suppressions.add("unchecked");
331	      suppressions.add("varargs");
332	    }
333	
334	    if (suppressions.isEmpty()) {
335	      return null;
336	    }
337	    // Enforce ordering across compilers (Internal and External compilers end up disagreeing on the
338	    // order produced by the Set additions above.)
339	    ArrayList<String> suppressionsList = new ArrayList<>(suppressions);
340	    Collections.sort(suppressionsList);
341	
342	    AnnotationSpec.Builder builder = AnnotationSpec.builder(SuppressWarnings.class);
343	    for (String suppression : suppressionsList) {
344	      builder.addMember("value", "$S", suppression);
345	    }
346	
347	    return builder.build();
348	  }
