350	  /**
351	   * Generates overrides of all methods in {@code com.bumptech.glide.RequestBuilder} that return
352	   * {@code com.bumptech.glide.RequestBuilder} so that they return our generated subclass instead.
353	   */
354	  private List<MethodSpec> generateRequestBuilderOverrides() {
355	    TypeMirror rawRequestBuilderType =
356	        processingEnv.getTypeUtils().erasure(requestBuilderType.asType());
357	    return Lists.transform(
358	        processorUtil.findInstanceMethodsReturning(requestBuilderType, rawRequestBuilderType),
359	        new Function<ExecutableElement, MethodSpec>() {
360	          @Override
361	          public MethodSpec apply(ExecutableElement input) {
362	            return generateRequestBuilderOverride(input);
363	          }
364	        });
