367	  /**
368	   * Generates an override of a particular method in {@code com.bumptech.glide.RequestBuilder} that
369	   * returns {@code com.bumptech.glide.RequestBuilder} so that it returns our generated subclass
370	   * instead.
371	   */
372	  private MethodSpec generateRequestBuilderOverride(ExecutableElement methodToOverride) {
373	    // We've already verified that this method returns a RequestBuilder and RequestBuilders have
374	    // exactly one type argument, so this is safe unless those assumptions change.
375	    TypeMirror typeArgument =
376	        ((DeclaredType) methodToOverride.getReturnType()).getTypeArguments().get(0);
377	
378	    ParameterizedTypeName generatedRequestBuilderOfType =
379	        ParameterizedTypeName.get(generatedRequestBuilderClassName, ClassName.get(typeArgument));
380	
381	    MethodSpec.Builder builder =
382	        processorUtil.overriding(methodToOverride).returns(generatedRequestBuilderOfType);
383	    builder.addCode(
384	        CodeBlock.builder()
385	            .add(
386	                "return ($T) super.$N(",
387	                generatedRequestBuilderOfType,
388	                methodToOverride.getSimpleName())
389	            .add(
390	                FluentIterable.from(builder.build().parameters)
391	                    .transform(
392	                        new Function<ParameterSpec, String>() {
393	                          @Override
394	                          public String apply(ParameterSpec input) {
395	                            return input.name;
396	                          }
397	                        })
398	                    .join(Joiner.on(", ")))
399	            .add(");\n")
400	            .build());
401	
402	    for (AnnotationMirror mirror : methodToOverride.getAnnotationMirrors()) {
403	      builder = builder.addAnnotation(AnnotationSpec.get(mirror));
404	    }
405	
406	    if (methodToOverride.isVarArgs()) {
407	      builder =
408	          builder
409	              .addModifiers(Modifier.FINAL)
410	              .addAnnotation(SafeVarargs.class)
411	              .addAnnotation(
412	                  AnnotationSpec.builder(SuppressWarnings.class)
413	                      .addMember("value", "$S", "varargs")
414	                      .build());
415	    }
416	
417	    return builder.build();
418	  }
