420	  private List<MethodSpec> generateConstructors() {
421	    ParameterizedTypeName classOfTranscodeType =
422	        ParameterizedTypeName.get(ClassName.get(Class.class), transcodeTypeName);
423	
424	    TypeName wildcardOfObject = WildcardTypeName.subtypeOf(Object.class);
425	    ParameterizedTypeName requestBuilderOfWildcardOfObject =
426	        ParameterizedTypeName.get(ClassName.get(requestBuilderType), wildcardOfObject);
427	
428	    MethodSpec firstConstructor =
429	        MethodSpec.constructorBuilder()
430	            .addParameter(
431	                ParameterSpec.builder(classOfTranscodeType, "transcodeClass")
432	                    .addAnnotation(processorUtil.nonNull())
433	                    .build())
434	            .addParameter(
435	                ParameterSpec.builder(requestBuilderOfWildcardOfObject, "other")
436	                    .addAnnotation(processorUtil.nonNull())
437	                    .build())
438	            .addStatement("super($N, $N)", "transcodeClass", "other")
439	            .build();
440	
441	    ClassName context = ClassName.get("android.content", "Context");
442	    ClassName glide = ClassName.get("com.bumptech.glide", "Glide");
443	    ClassName requestManager = ClassName.get("com.bumptech.glide", "RequestManager");
444	    MethodSpec secondConstructor =
445	        MethodSpec.constructorBuilder()
446	            .addParameter(
447	                ParameterSpec.builder(glide, "glide")
448	                    .addAnnotation(processorUtil.nonNull())
449	                    .build())
450	            .addParameter(
451	                ParameterSpec.builder(requestManager, "requestManager")
452	                    .addAnnotation(processorUtil.nonNull())
453	                    .build())
454	            .addParameter(
455	                ParameterSpec.builder(classOfTranscodeType, "transcodeClass")
456	                    .addAnnotation(processorUtil.nonNull())
457	                    .build())
458	            .addParameter(
459	                ParameterSpec.builder(context, "context")
460	                    .addAnnotation(processorUtil.nonNull())
461	                    .build())
462	            .addStatement(
463	                "super($N, $N ,$N, $N)", "glide", "requestManager", "transcodeClass", "context")
464	            .build();
465	    return ImmutableList.of(firstConstructor, secondConstructor);
466	  }
