468	  /**
469	   * Overrides the protected downloadOnly method in {@code com.bumptech.glide.RequestBuilder} to
470	   * return our generated subclass instead.
471	   */
472	  private MethodSpec generateDownloadOnlyRequestMethod() {
473	    ParameterizedTypeName generatedRequestBuilderOfFile =
474	        ParameterizedTypeName.get(generatedRequestBuilderClassName, ClassName.get(File.class));
475	    return MethodSpec.methodBuilder("getDownloadOnlyRequest")
476	        .addAnnotation(Override.class)
477	        .addAnnotation(processorUtil.checkResult())
478	        .addAnnotation(processorUtil.nonNull())
479	        .returns(generatedRequestBuilderOfFile)
480	        .addModifiers(Modifier.PROTECTED)
481	        .addStatement(
482	            "return new $T<>($T.class, $N).apply($N)",
483	            generatedRequestBuilderClassName,
484	            File.class,
485	            "this",
486	            "DOWNLOAD_ONLY_OPTIONS")
487	        .build();
488	  }
