78	    Elements elementUtils = processingEnv.getElementUtils();
79	
80	    requestManagerType = elementUtils.getTypeElement(REQUEST_MANAGER_QUALIFIED_NAME);
81	    requestManagerClassName = ClassName.get(requestManagerType);
82	
83	    lifecycleType = elementUtils.getTypeElement(LIFECYCLE_QUALIFIED_NAME);
84	    requestManagerTreeNodeType =
85	        elementUtils.getTypeElement(REQUEST_MANAGER_TREE_NODE_QUALIFIED_NAME);
86	
87	    requestBuilderType =
88	        elementUtils.getTypeElement(RequestBuilderGenerator.REQUEST_BUILDER_QUALIFIED_NAME);
89	
90	    glideType = elementUtils.getTypeElement(GLIDE_QUALIFIED_NAME);
91	  }
92	
93	  TypeSpec generate(
94	      String generatedCodePackageName,
95	      @Nullable TypeSpec requestOptions,
96	      TypeSpec requestBuilder,
97	      Set<String> glideExtensions) {
98	    generatedRequestBuilderClassName = ClassName.get(generatedCodePackageName, requestBuilder.name);
99	    return TypeSpec.classBuilder(GENERATED_REQUEST_MANAGER_SIMPLE_NAME)
100	        .superclass(requestManagerClassName)
101	        .addJavadoc(
102	            "Includes all additions from methods in {@link $T}s\n"
103	                + "annotated with {@link $T}\n"
104	                + "\n"
105	                + "<p>Generated code, do not modify\n",
106	            GlideExtension.class,
107	            GlideType.class)
108	        .addAnnotation(
109	            AnnotationSpec.builder(SuppressWarnings.class)
110	                .addMember("value", "$S", "deprecation")
111	                .build())
112	        .addModifiers(Modifier.PUBLIC)
113	        .addMethod(generateAsMethod(generatedCodePackageName, requestBuilder))
114	        .addMethod(generateCallSuperConstructor())
115	        .addMethods(generateExtensionRequestManagerMethods(glideExtensions))
116	        .addMethods(generateRequestManagerRequestManagerMethodOverrides(generatedCodePackageName))
117	        .addMethods(generateRequestManagerRequestBuilderMethodOverrides())
118	        .addMethods(
119	            FluentIterable.from(
120	                    Collections.singletonList(
121	                        generateOverrideSetRequestOptions(
122	                            generatedCodePackageName, requestOptions)))
123	                .filter(Predicates.<MethodSpec>notNull()))
124	        .build();
125	  }
126	
127	  private MethodSpec generateCallSuperConstructor() {
128	    return MethodSpec.constructorBuilder()
129	        .addModifiers(Modifier.PUBLIC)
130	        .addParameter(
131	            ParameterSpec.builder(ClassName.get(glideType), "glide")
132	                .addAnnotation(processorUtil.nonNull())
133	                .build())
134	        .addParameter(
135	            ParameterSpec.builder(ClassName.get(lifecycleType), "lifecycle")
136	                .addAnnotation(processorUtil.nonNull())
137	                .build())
138	        .addParameter(
139	            ParameterSpec.builder(ClassName.get(requestManagerTreeNodeType), "treeNode")
140	                .addAnnotation(processorUtil.nonNull())
141	                .build())
142	        .addParameter(
143	            ParameterSpec.builder(CONTEXT_CLASS_NAME, "context")
144	                .addAnnotation(processorUtil.nonNull())
145	                .build())
146	        .addStatement("super(glide, lifecycle, treeNode, context)")
147	        .build();
148	  }
149	
150	  private MethodSpec generateAsMethod(String generatedCodePackageName, TypeSpec requestBuilder) {
151	    TypeVariableName resourceType = TypeVariableName.get("ResourceType");
152	    ParameterizedTypeName classOfResouceType =
153	        ParameterizedTypeName.get(ClassName.get(Class.class), resourceType);
154	
155	    ClassName generatedRequestBuilderClassName =
156	        ClassName.get(generatedCodePackageName, requestBuilder.name);
157	
158	    ParameterizedTypeName requestBuilderOfResourceType =
159	        ParameterizedTypeName.get(generatedRequestBuilderClassName, resourceType);
160	
161	    return MethodSpec.methodBuilder("as")
162	        .addModifiers(Modifier.PUBLIC)
163	        .addAnnotation(Override.class)
164	        .addAnnotation(processorUtil.checkResult())
165	        .addAnnotation(processorUtil.nonNull())
166	        .addTypeVariable(TypeVariableName.get("ResourceType"))
167	        .returns(requestBuilderOfResourceType)
168	        .addParameter(
169	            classOfResouceType.annotated(AnnotationSpec.builder(processorUtil.nonNull()).build()),
170	            "resourceClass")
171	        .addStatement(
172	            "return new $T<>(glide, this, resourceClass, context)",
173	            this.generatedRequestBuilderClassName)
174	        .build();
175	  }
176	
177	  /** Generates the list of overrides of methods that return {@code RequestManager}. */
178	  private List<MethodSpec> generateRequestManagerRequestManagerMethodOverrides(
179	      final String generatedPackageName) {
180	    return FluentIterable.from(
181	            processorUtil.findInstanceMethodsReturning(requestManagerType, requestManagerType))
182	        .transform(
183	            new Function<ExecutableElement, MethodSpec>() {
184	              @Override
185	              public MethodSpec apply(@Nullable ExecutableElement input) {
186	                return generateRequestManagerRequestManagerMethodOverride(
187	                    generatedPackageName, input);
188	              }
189	            })
190	        .toList();
191	  }
192	
193	  private MethodSpec generateRequestManagerRequestManagerMethodOverride(
194	      String generatedPackageName, ExecutableElement method) {
195	    ClassName generatedRequestManagerName =
196	        ClassName.get(generatedPackageName, GENERATED_REQUEST_MANAGER_SIMPLE_NAME);
197	    Builder returns =
198	        processorUtil
199	            .overriding(method)
200	            .addAnnotation(processorUtil.nonNull())
201	            .returns(generatedRequestManagerName);
202	    return returns
203	        .addCode(
204	            ProcessorUtil.generateCastingSuperCall(generatedRequestManagerName, returns.build()))
205	        .build();
206	  }
207	
208	  /** Generates the list of overrides of methods that return {@code RequestBuilder}. */
209	  private List<MethodSpec> generateRequestManagerRequestBuilderMethodOverrides() {
210	    // Without the erasure, this is a RequestBuilder<Y>. A RequestBuilder<X> is not assignable to a
211	    // RequestBuilder<Y>. After type erasure this is a RequestBuilder. A RequestBuilder<X> is
212	    // assignable to the raw RequestBuilder.
213	    TypeMirror rawRequestBuilder =
214	        processingEnv.getTypeUtils().erasure(requestBuilderType.asType());
215	
216	    return FluentIterable.from(
217	            processorUtil.findInstanceMethodsReturning(requestManagerType, rawRequestBuilder))
218	        .filter(
219	            new Predicate<ExecutableElement>() {
220	              @Override
221	              public boolean apply(ExecutableElement input) {
222	                // Skip the <T> as(Class<T>) method.
223	                return !input.getSimpleName().toString().equals("as");
224	              }
225	            })
226	        .transform(
227	            new Function<ExecutableElement, MethodSpec>() {
228	              @Override
229	              public MethodSpec apply(ExecutableElement input) {
230	                return generateRequestManagerRequestBuilderMethodOverride(input);
231	              }
232	            })
233	        .toList();
234	  }
235	
236	  /**
237	   * Generates overrides of existing RequestManager methods so that they return our generated
238	   * RequestBuilder subtype.
239	   */
240	  private MethodSpec generateRequestManagerRequestBuilderMethodOverride(
241	      ExecutableElement methodToOverride) {
242	    // We've already verified that this method returns a RequestBuilder and RequestBuilders have
243	    // exactly one type argument, so this is safe unless those assumptions change.
244	    TypeMirror typeArgument =
245	        ((DeclaredType) methodToOverride.getReturnType()).getTypeArguments().get(0);
246	
247	    ParameterizedTypeName generatedRequestBuilderOfType =
248	        ParameterizedTypeName.get(generatedRequestBuilderClassName, ClassName.get(typeArgument));
249	
250	    MethodSpec.Builder builder =
251	        processorUtil.overriding(methodToOverride).returns(generatedRequestBuilderOfType);
252	    builder.addCode(
253	        ProcessorUtil.generateCastingSuperCall(generatedRequestBuilderOfType, builder.build()));
254	
255	    for (AnnotationMirror mirror : methodToOverride.getAnnotationMirrors()) {
256	      builder.addAnnotation(AnnotationSpec.get(mirror));
257	    }
258	    return builder.build();
259	  }
260	
261	  private List<MethodSpec> generateExtensionRequestManagerMethods(Set<String> glideExtensions) {
262	    List<ExecutableElement> requestManagerExtensionMethods =
263	        processorUtil.findAnnotatedElementsInClasses(glideExtensions, GlideType.class);
264	
265	    return Lists.transform(
266	        requestManagerExtensionMethods,
267	        new Function<ExecutableElement, MethodSpec>() {
268	          @Override
269	          public MethodSpec apply(ExecutableElement input) {
270	            return generateAdditionalRequestManagerMethod(input);
271	          }
272	        });
273	  }
274	
275	  // Generates methods added to RequestManager via GlideExtensions.
276	  private MethodSpec generateAdditionalRequestManagerMethod(ExecutableElement extensionMethod) {
277	    if (extensionMethod.getReturnType().getKind() == TypeKind.VOID) {
278	      return generateAdditionalRequestManagerMethodLegacy(extensionMethod);
279	    } else {
280	      return generateAdditionalRequestManagerMethodNew(extensionMethod);
281	    }
282	  }
283	
284	  private MethodSpec generateAdditionalRequestManagerMethodLegacy(
285	      ExecutableElement extensionMethod) {
286	    String returnType =
287	        processorUtil
288	            .findClassValuesFromAnnotationOnClassAsNames(extensionMethod, GlideType.class)
289	            .iterator()
290	            .next();
291	    ClassName returnTypeClassName = ClassName.bestGuess(returnType);
292	    ParameterizedTypeName parameterizedTypeName =
293	        ParameterizedTypeName.get(generatedRequestBuilderClassName, returnTypeClassName);
294	
295	    return MethodSpec.methodBuilder(extensionMethod.getSimpleName().toString())
296	        .addModifiers(Modifier.PUBLIC)
297	        .returns(parameterizedTypeName)
298	        .addJavadoc(processorUtil.generateSeeMethodJavadoc(extensionMethod))
299	        .addAnnotation(processorUtil.nonNull())
300	        .addAnnotation(processorUtil.checkResult())
301	        .addStatement(
302	            "$T requestBuilder = this.as($T.class)", parameterizedTypeName, returnTypeClassName)
303	        .addStatement(
304	            "$T.$N(requestBuilder)",
305	            extensionMethod.getEnclosingElement(),
306	            extensionMethod.getSimpleName())
307	        .addStatement("return requestBuilder")
308	        .build();
309	  }
310	
311	  private MethodSpec generateAdditionalRequestManagerMethodNew(ExecutableElement extensionMethod) {
312	    String returnType =
313	        processorUtil
314	            .findClassValuesFromAnnotationOnClassAsNames(extensionMethod, GlideType.class)
315	            .iterator()
316	            .next();
317	    ClassName returnTypeClassName = ClassName.bestGuess(returnType);
318	    ParameterizedTypeName parameterizedTypeName =
319	        ParameterizedTypeName.get(generatedRequestBuilderClassName, returnTypeClassName);
320	
321	    return MethodSpec.methodBuilder(extensionMethod.getSimpleName().toString())
322	        .addModifiers(Modifier.PUBLIC)
323	        .returns(parameterizedTypeName)
324	        .addJavadoc(processorUtil.generateSeeMethodJavadoc(extensionMethod))
325	        .addAnnotation(processorUtil.nonNull())
326	        .addAnnotation(processorUtil.checkResult())
327	        .addStatement(
328	            "return ($T) $T.$N(this.as($T.class))",
329	            parameterizedTypeName,
330	            extensionMethod.getEnclosingElement(),
331	            extensionMethod.getSimpleName(),
332	            returnTypeClassName)
333	        .build();
334	  }
335	
336	  /**
337	   * The {@code RequestOptions} subclass should always be our generated subclass type to avoid
338	   * inadvertent errors where a different subclass is applied that accidentally wipes out some logic
339	   * in overidden methods in our generated subclass.
340	   */
341	  @Nullable
342	  private MethodSpec generateOverrideSetRequestOptions(
343	      String generatedCodePackageName, @Nullable TypeSpec generatedRequestOptions) {
344	    if (generatedRequestOptions == null) {
345	      return null;
346	    }
347	
348	    Elements elementUtils = processingEnv.getElementUtils();
349	    TypeElement requestOptionsType =
350	        elementUtils.getTypeElement(RequestOptionsGenerator.REQUEST_OPTIONS_QUALIFIED_NAME);
351	
352	    // This class may have just been generated and therefore may not be found if we try to obtain
353	    // it via Elements, so use just the String version instead.
354	    String generatedRequestOptionsQualifiedName =
355	        generatedCodePackageName + "." + generatedRequestOptions.name;
356	
357	    String methodName = "setRequestOptions";
358	    String parameterName = "toSet";
359	
360	    return MethodSpec.methodBuilder(methodName)
361	        .addAnnotation(Override.class)
362	        .addModifiers(Modifier.PROTECTED)
363	        .addParameter(
364	            ParameterSpec.builder(ClassName.get(requestOptionsType), parameterName)
365	                .addAnnotation(processorUtil.nonNull())
366	                .build())
367	        .beginControlFlow(
368	            "if ($N instanceof $L)", parameterName, generatedRequestOptionsQualifiedName)
369	        .addStatement("super.$N($N)", methodName, parameterName)
370	        .nextControlFlow("else")
371	        .addStatement(
372	            "super.setRequestOptions(new $L().apply($N))",
373	            generatedRequestOptionsQualifiedName,
374	            parameterName)
375	        .endControlFlow()
376	        .build();
377	  }
378	}
