1	package com.bumptech.glide.annotation.compiler;
2	
3	import com.bumptech.glide.annotation.GlideModule;
4	import com.squareup.javapoet.TypeSpec;
5	import java.util.ArrayList;
6	import java.util.Collections;
7	import java.util.HashSet;
8	import java.util.List;
9	import java.util.Set;
10	import javax.annotation.processing.ProcessingEnvironment;
11	import javax.annotation.processing.RoundEnvironment;
12	import javax.lang.model.element.Element;
13	import javax.lang.model.element.PackageElement;
14	import javax.lang.model.element.TypeElement;
15	
16	/**
17	 * Runs the final steps of Glide's annotation process and generates the combined {@code
18	 * AppGlideModule}, {@code com.bumptech.glide.Glide}, {@code com.bumptech.glide.RequestManager}, and
19	 * {@code com.bumptech.glide.request.RequestOptions} classes.
20	 */
21	final class AppModuleProcessor {
22	  private static final String COMPILER_PACKAGE_NAME =
23	      GlideAnnotationProcessor.class.getPackage().getName();
24	
25	  private final ProcessingEnvironment processingEnv;
26	  private final ProcessorUtil processorUtil;
27	  private final List<TypeElement> appGlideModules = new ArrayList<>();
28	  private final RequestOptionsGenerator requestOptionsGenerator;
29	  private final RequestManagerGenerator requestManagerGenerator;
30	  private final AppModuleGenerator appModuleGenerator;
31	  private final RequestBuilderGenerator requestBuilderGenerator;
32	  private final RequestManagerFactoryGenerator requestManagerFactoryGenerator;
33	  private final GlideGenerator glideGenerator;
34	
35	  AppModuleProcessor(ProcessingEnvironment processingEnv, ProcessorUtil processorUtil) {
36	    this.processingEnv = processingEnv;
37	    this.processorUtil = processorUtil;
38	
39	    appModuleGenerator = new AppModuleGenerator(processingEnv, processorUtil);
40	    requestOptionsGenerator = new RequestOptionsGenerator(processingEnv, processorUtil);
41	    requestManagerGenerator = new RequestManagerGenerator(processingEnv, processorUtil);
42	    requestManagerFactoryGenerator =
43	        new RequestManagerFactoryGenerator(processingEnv, processorUtil);
44	    glideGenerator = new GlideGenerator(processingEnv, processorUtil);
45	    requestBuilderGenerator = new RequestBuilderGenerator(processingEnv, processorUtil);
46	  }
47	
48	  void processModules(Set<? extends TypeElement> set, RoundEnvironment env) {
49	    for (TypeElement element : processorUtil.getElementsFor(GlideModule.class, env)) {
50	      if (processorUtil.isAppGlideModule(element)) {
51	        appGlideModules.add(element);
52	      }
53	    }
54	
55	    processorUtil.debugLog("got app modules: " + appGlideModules);
56	
57	    if (appGlideModules.size() > 1) {
58	      throw new IllegalStateException(
59	          "You cannot have more than one AppGlideModule, found: " + appGlideModules);
60	    }
61	  }
62	
63	  boolean maybeWriteAppModule() {
64	    // appGlideModules is added to in order to catch errors where multiple AppGlideModules may be
65	    // present for a single application or library. Because we only add to appGlideModules, we use
66	    // isGeneratedAppGlideModuleWritten to make sure the GeneratedAppGlideModule is written at
67	    // most once.
68	    if (appGlideModules.isEmpty()) {
69	      return false;
70	    }
71	    TypeElement appModule = appGlideModules.get(0);
72	    processorUtil.debugLog("Processing app module: " + appModule);
73	    // If this package is null, it means there are no classes with this package name. One way this
74	    // could happen is if we process an annotation and reach this point without writing something
75	    // to the package. We do not error check here because that shouldn't happen with the
76	    // current implementation.
77	    PackageElement glideGenPackage =
78	        processingEnv.getElementUtils().getPackageElement(COMPILER_PACKAGE_NAME);
79	    FoundIndexedClassNames indexedClassNames = getIndexedClassNames(glideGenPackage);
80	
81	    // Write all generated code to the package containing the AppGlideModule. Doing so fixes
82	    // classpath collisions if more than one Application containing a AppGlideModule is included
83	    // in a project.
84	    String generatedCodePackageName = appModule.getEnclosingElement().toString();
85	
86	    TypeSpec generatedRequestOptions =
87	        requestOptionsGenerator.generate(generatedCodePackageName, indexedClassNames.extensions);
88	    writeRequestOptions(generatedCodePackageName, generatedRequestOptions);
89	
90	    TypeSpec generatedRequestBuilder =
91	        requestBuilderGenerator.generate(
92	            generatedCodePackageName, indexedClassNames.extensions, generatedRequestOptions);
93	    writeRequestBuilder(generatedCodePackageName, generatedRequestBuilder);
94	
95	    TypeSpec requestManager =
96	        requestManagerGenerator.generate(
97	            generatedCodePackageName,
98	            generatedRequestOptions,
99	            generatedRequestBuilder,
100	            indexedClassNames.extensions);
101	    writeRequestManager(generatedCodePackageName, requestManager);
102	
103	    TypeSpec requestManagerFactory =
104	        requestManagerFactoryGenerator.generate(generatedCodePackageName, requestManager);
105	    writeRequestManagerFactory(requestManagerFactory);
106	
107	    TypeSpec glide =
108	        glideGenerator.generate(generatedCodePackageName, getGlideName(appModule), requestManager);
109	    writeGlide(generatedCodePackageName, glide);
110	
111	    TypeSpec generatedAppGlideModule =
112	        appModuleGenerator.generate(appModule, indexedClassNames.glideModules);
113	    writeAppModule(generatedAppGlideModule);
114	
115	    processorUtil.infoLog("Wrote GeneratedAppGlideModule with: " + indexedClassNames.glideModules);
116	
117	    return true;
118	  }
119	
120	  private String getGlideName(TypeElement appModule) {
121	    return appModule.getAnnotation(GlideModule.class).glideName();
122	  }
123	
124	  @SuppressWarnings("unchecked")
125	  private FoundIndexedClassNames getIndexedClassNames(PackageElement glideGenPackage) {
126	    Set<String> glideModules = new HashSet<>();
127	    Set<String> extensions = new HashSet<>();
128	    List<? extends Element> glideGeneratedElements = glideGenPackage.getEnclosedElements();
129	    for (Element indexer : glideGeneratedElements) {
130	      Index annotation = indexer.getAnnotation(Index.class);
131	      // If the annotation is null, it means we've come across another class in the same package
132	      // that we can safely ignore.
133	      if (annotation != null) {
134	        Collections.addAll(glideModules, annotation.modules());
135	        Collections.addAll(extensions, annotation.extensions());
136	      }
137	    }
138	
139	    processorUtil.debugLog("Found GlideModules: " + glideModules);
140	    return new FoundIndexedClassNames(glideModules, extensions);
141	  }
142	
143	  private void writeGlide(String packageName, TypeSpec glide) {
144	    processorUtil.writeClass(packageName, glide);
145	  }
146	
147	  private void writeRequestManager(String packageName, TypeSpec requestManager) {
148	    processorUtil.writeClass(packageName, requestManager);
149	  }
150	
151	  // We dont' care about collisions in IDEs since this class isn't an API class.
152	  private void writeRequestManagerFactory(TypeSpec requestManagerFactory) {
153	    processorUtil.writeClass(
154	        AppModuleGenerator.GENERATED_ROOT_MODULE_PACKAGE_NAME, requestManagerFactory);
155	  }
156	
157	  // The app module we generate subclasses a package private class. We don't care about classpath
158	  // collisions in IDEs since this class isn't an API class.
159	  private void writeAppModule(TypeSpec appModule) {
160	    processorUtil.writeClass(AppModuleGenerator.GENERATED_ROOT_MODULE_PACKAGE_NAME, appModule);
161	  }
162	
163	  private void writeRequestOptions(String packageName, TypeSpec requestOptions) {
164	    processorUtil.writeClass(packageName, requestOptions);
165	  }
166	
167	  private void writeRequestBuilder(String packageName, TypeSpec requestBuilder) {
168	    processorUtil.writeClass(packageName, requestBuilder);
169	  }
170	
171	  private static final class FoundIndexedClassNames {
172	    private final Set<String> glideModules;
173	    private final Set<String> extensions;
174	
175	    private FoundIndexedClassNames(Set<String> glideModules, Set<String> extensions) {
176	      this.glideModules = glideModules;
177	      this.extensions = extensions;
178	    }
179	  }
180	}
