12	/**
13	 * Writes Indexer classes annotated with {@link Index} for all classes found annotated with {@link
14	 * GlideExtension}.
15	 */
16	final class ExtensionProcessor {
17	  private final ProcessorUtil processorUtil;
18	  private final IndexerGenerator indexerGenerator;
19	  private final GlideExtensionValidator extensionValidator;
20	
21	  ExtensionProcessor(
22	      ProcessingEnvironment processingEnvironment,
23	      ProcessorUtil processorUtil,
24	      IndexerGenerator indexerGenerator,
25	      boolean useLegacyTypeComparison) {
26	    this.processorUtil = processorUtil;
27	    this.indexerGenerator = indexerGenerator;
28	    extensionValidator =
29	        new GlideExtensionValidator(processingEnvironment, processorUtil, useLegacyTypeComparison);
30	  }
31	
32	  boolean processExtensions(RoundEnvironment env) {
33	    List<TypeElement> elements = processorUtil.getElementsFor(GlideExtension.class, env);
34	    processorUtil.debugLog("Processing types : " + elements);
35	    for (TypeElement typeElement : elements) {
36	      extensionValidator.validateExtension(typeElement);
37	      processorUtil.debugLog("Processing elements: " + typeElement.getEnclosedElements());
38	    }
39	
40	    if (elements.isEmpty()) {
41	      return false;
42	    }
43	    TypeSpec spec = indexerGenerator.generate(elements);
44	    processorUtil.writeIndexer(spec);
45	    return true;
46	  }
47	
48	  Set<String> getSupportedAnnotationTypes() {
49	    return Collections.singleton(GlideExtension.class.getName());
50	  }
51	}
