27	 * configurable in {@link com.bumptech.glide.annotation.GlideModule}):
28	 *
29	 * <pre>
30	 * <code>
31	 * public final class GlideApp {
32	 *   private GiphyGlide() {
33	 *   }
34	 *
35	 *   public static File getPhotoCacheDir(Context context) {
36	 *     return Glide.getPhotoCacheDir(context);
37	 *   }
38	 *
39	 *   public static File getPhotoCacheDir(Context context, String cacheName) {
40	 *     return Glide.getPhotoCacheDir(context, cacheName);
41	 *   }
42	 *
43	 *   public static Glide get(Context context) {
44	 *     return Glide.get(context);
45	 *   }
46	 *
47	 *   public static void tearDown() {
48	 *     Glide.tearDown();
49	 *   }
50	 *
51	 *   public static GeneratedRequestManager with(Context context) {
52	 *     return (GeneratedRequestManager) Glide.with(context);
53	 *   }
54	 *
55	 *   public static GeneratedRequestManager with(Activity activity) {
56	 *    return (GeneratedRequestManager) Glide.with(activity);
57	 *   }
58	 *
59	 *   public static GeneratedRequestManager with(FragmentActivity activity) {
60	 *     return (GeneratedRequestManager) Glide.with(activity);
61	 *   }
62	 *
63	 *   public static GeneratedRequestManager with(Fragment fragment) {
64	 *     return (GeneratedRequestManager) Glide.with(fragment);
65	 *   }
66	 *
67	 *   public static GeneratedRequestManager with(androidx.fragment.app.Fragment fragment) {
68	 *     return (GeneratedRequestManager) Glide.with(fragment);
69	 *   }
70	 * </code>
71	 * </pre>
72	 */
73	final class GlideGenerator {
74	  private static final String GLIDE_QUALIFIED_NAME = "com.bumptech.glide.Glide";
75	
76	  private static final String REQUEST_MANAGER_QUALIFIED_NAME = "com.bumptech.glide.RequestManager";
77	
78	  private static final String SUPPRESS_LINT_PACKAGE_NAME = "android.annotation";
79	  private static final String SUPPRESS_LINT_CLASS_NAME = "SuppressLint";
80	
81	  private final ProcessingEnvironment processingEnv;
82	  private final ProcessorUtil processorUtil;
83	  private final TypeElement glideType;
84	  private final TypeElement requestManagerType;
85	
86	  GlideGenerator(ProcessingEnvironment processingEnv, ProcessorUtil processorUtil) {
87	    this.processingEnv = processingEnv;
88	    this.processorUtil = processorUtil;
89	
90	    Elements elementUtils = processingEnv.getElementUtils();
91	
92	    requestManagerType = elementUtils.getTypeElement(REQUEST_MANAGER_QUALIFIED_NAME);
93	
94	    glideType = elementUtils.getTypeElement(GLIDE_QUALIFIED_NAME);
95	  }
96	
97	  TypeSpec generate(
98	      String generatedCodePackageName, String glideName, TypeSpec generatedRequestManager) {
99	    return TypeSpec.classBuilder(glideName)
100	        .addJavadoc(
101	            "The entry point for interacting with Glide for Applications\n"
102	                + "\n"
103	                + "<p>Includes all generated APIs from all\n"
104	                + "{@link $T}s in source and dependent libraries.\n"
105	                + "\n"
106	                + "<p>This class is generated and should not be modified"
107	                + "\n"
108	                + "@see $T\n",
109	            GlideExtension.class,
110	            glideType)
111	        .addModifiers(Modifier.PUBLIC, Modifier.FINAL)
112	        .addMethod(MethodSpec.constructorBuilder().addModifiers(Modifier.PRIVATE).build())
113	        .addMethods(
114	            generateOverridesForGlideMethods(generatedCodePackageName, generatedRequestManager))
115	        .build();
116	  }
117	
118	  private List<MethodSpec> generateOverridesForGlideMethods(
119	      final String generatedCodePackageName, final TypeSpec generatedRequestManager) {
120	    return Lists.transform(
121	        discoverGlideMethodsToOverride(),
122	        new Function<ExecutableElement, MethodSpec>() {
123	          @Override
124	          public MethodSpec apply(ExecutableElement input) {
125	            if (isGlideWithMethod(input)) {
126	              return overrideGlideWithMethod(
127	                  generatedCodePackageName, generatedRequestManager, input);
128	            } else {
129	              return overrideGlideStaticMethod(input);
130	            }
131	          }
132	        });
133	  }
134	
135	  private MethodSpec overrideGlideStaticMethod(ExecutableElement methodToOverride) {
136	    List<ParameterSpec> parameters = processorUtil.getParameters(methodToOverride);
137	
138	    TypeElement element =
139	        (TypeElement) processingEnv.getTypeUtils().asElement(methodToOverride.getReturnType());
140	
141	    MethodSpec.Builder builder =
142	        MethodSpec.methodBuilder(methodToOverride.getSimpleName().toString())
143	            .addModifiers(Modifier.PUBLIC, Modifier.STATIC)
144	            .addJavadoc(processorUtil.generateSeeMethodJavadoc(methodToOverride))
145	            .addParameters(parameters);
146	
147	    addReturnAnnotations(builder, methodToOverride);
148	
149	    boolean returnsValue = element != null;
150	    if (returnsValue) {
151	      builder.returns(ClassName.get(element));
152	    }
153	
154	    StringBuilder code = new StringBuilder(returnsValue ? "return " : "");
155	    code.append("$T.$N(");
156	    List<Object> args = new ArrayList<>();
157	    args.add(ClassName.get(glideType));
158	    args.add(methodToOverride.getSimpleName());
159	    if (!parameters.isEmpty()) {
160	      for (ParameterSpec param : parameters) {
161	        code.append("$L, ");
162	        args.add(param.name);
163	      }
164	      code = new StringBuilder(code.substring(0, code.length() - 2));
165	    }
166	    code.append(")");
167	    builder.addStatement(code.toString(), args.toArray(new Object[0]));
168	    return builder.build();
169	  }
170	
171	  private Builder addReturnAnnotations(Builder builder, ExecutableElement methodToOverride) {
172	    Elements elements = processingEnv.getElementUtils();
173	    TypeElement visibleForTestingTypeElement =
174	        elements.getTypeElement(processorUtil.visibleForTesting().reflectionName());
175	    String visibleForTestingTypeQualifiedName = visibleForTestingTypeElement.toString();
176	
177	    for (AnnotationMirror mirror : methodToOverride.getAnnotationMirrors()) {
178	      builder.addAnnotation(AnnotationSpec.get(mirror));
179	
180	      // Suppress a lint warning if we're overriding a VisibleForTesting method.
181	      // See #1977.
182	      String annotationQualifiedName = mirror.getAnnotationType().toString();
183	      if (annotationQualifiedName.equals(visibleForTestingTypeQualifiedName)) {
184	        builder.addAnnotation(
185	            AnnotationSpec.builder(
186	                    ClassName.get(SUPPRESS_LINT_PACKAGE_NAME, SUPPRESS_LINT_CLASS_NAME))
187	                .addMember("value", "$S", "VisibleForTests")
188	                .build());
189	      }
190	    }
191	
192	    return builder;
193	  }
194	
195	  private List<ExecutableElement> discoverGlideMethodsToOverride() {
196	    return processorUtil.findStaticMethods(glideType);
197	  }
198	
199	  private boolean isGlideWithMethod(ExecutableElement element) {
200	    return processorUtil.isReturnValueTypeMatching(element, requestManagerType);
201	  }
202	
203	  private MethodSpec overrideGlideWithMethod(
204	      String packageName, TypeSpec generatedRequestManager, ExecutableElement methodToOverride) {
205	    ClassName generatedRequestManagerClassName =
206	        ClassName.get(packageName, generatedRequestManager.name);
207	    List<ParameterSpec> parameters = processorUtil.getParameters(methodToOverride);
208	    Preconditions.checkArgument(
209	        parameters.size() == 1, "Expected size of 1, but got %s", methodToOverride);
210	    ParameterSpec parameter = parameters.iterator().next();
211	
212	    Builder builder =
213	        MethodSpec.methodBuilder(methodToOverride.getSimpleName().toString())
214	            .addModifiers(Modifier.PUBLIC, Modifier.STATIC)
215	            .addJavadoc(processorUtil.generateSeeMethodJavadoc(methodToOverride))
216	            .addParameters(parameters)
217	            .returns(generatedRequestManagerClassName)
218	            .addStatement(
219	                "return ($T) $T.$N($L)",
220	                generatedRequestManagerClassName,
221	                glideType,
222	                methodToOverride.getSimpleName().toString(),
223	                parameter.name);
224	
225	    return addReturnAnnotations(builder, methodToOverride).build();
226	  }
227	}
