2	
3	import com.bumptech.glide.annotation.GlideExtension;
4	import com.bumptech.glide.annotation.GlideModule;
5	import com.squareup.javapoet.AnnotationSpec;
6	import com.squareup.javapoet.ClassName;
7	import com.squareup.javapoet.TypeSpec;
8	import java.lang.annotation.Annotation;
9	import java.util.ArrayList;
10	import java.util.Comparator;
11	import java.util.List;
12	import java.util.UUID;
13	import javax.lang.model.element.Modifier;
14	import javax.lang.model.element.TypeElement;
15	
16	/**
17	 * Generates an empty class with an annotation containing the class names of one or more
18	 * LibraryGlideModules and/or one or more GlideExtensions.
19	 *
20	 * <p>We use a separate class so that LibraryGlideModules and GlideExtensions written in libraries
21	 * can be bundled into an AAR and later retrieved by the annotation processor when it processes the
22	 * AppGlideModule in an application.
23	 *
24	 * <p>The output file generated by this class with a LibraryGlideModule looks like this:
25	 *
26	 * <pre>
27	 * <code>
28	 *  {@literal @com.bumptech.glide.annotation.compiler.Index(}
29	 *      modules = "com.bumptech.glide.integration.okhttp3.OkHttpLibraryGlideModule"
30	 *  )
31	 *  public class Indexer_GlideModule_com_bumptech_glide_integration_okhttp3_OkHttpLibraryGlideModule
32	 *  {
33	 *  }
34	 * </code>
35	 * </pre>
36	 *
37	 * <p>The output file generated by this class with a GlideExtension looks like this:
38	 *
39	 * <pre>
40	 * <code>
41	 *  {@literal @com.bumptech.glide.annotation.compiler.Index(}
42	 *      extensions = "com.bumptech.glide.integration.gif.GifOptions"
43	 *  )
44	 *  public class Indexer_GlideExtension_com_bumptech_glide_integration_gif_GifOptions {
45	 *  }
46	 * </code>
47	 * </pre>
48	 */
49	final class IndexerGenerator {
50	  private static final String INDEXER_NAME_PREFIX = "GlideIndexer_";
51	  private static final int MAXIMUM_FILE_NAME_LENGTH = 255;
52	  private final ProcessorUtil processorUtil;
53	
54	  IndexerGenerator(ProcessorUtil processorUtil) {
55	    this.processorUtil = processorUtil;
56	  }
57	
58	  TypeSpec generate(List<TypeElement> types) {
59	    List<TypeElement> modules = new ArrayList<>();
60	    List<TypeElement> extensions = new ArrayList<>();
61	    for (TypeElement element : types) {
62	      if (processorUtil.isExtension(element)) {
63	        extensions.add(element);
64	      } else if (processorUtil.isLibraryGlideModule(element)) {
65	        modules.add(element);
66	      } else {
67	        throw new IllegalArgumentException("Unrecognized type: " + element);
68	      }
69	    }
70	    if (!modules.isEmpty() && !extensions.isEmpty()) {
71	      throw new IllegalArgumentException(
72	          "Given both modules and extensions, expected one or the "
73	              + "other. Modules: "
74	              + modules
75	              + " Extensions: "
76	              + extensions);
77	    }
78	    if (!modules.isEmpty()) {
79	      return generate(types, GlideModule.class);
80	    } else {
81	      return generate(types, GlideExtension.class);
82	    }
83	  }
84	
85	  private TypeSpec generate(
86	      List<TypeElement> libraryModules, Class<? extends Annotation> annotation) {
87	    // Sort modules by qualified name to ensure deterministic ordering
88	    List<TypeElement> sortedModules = new ArrayList<>(libraryModules);
89	    sortedModules.sort(Comparator.comparing(a -> a.getQualifiedName().toString()));
90	
91	    AnnotationSpec.Builder annotationBuilder = AnnotationSpec.builder(Index.class);
92	
93	    String value = getAnnotationValue(annotation);
94	    for (TypeElement childModule : sortedModules) {
95	      annotationBuilder.addMember(value, "$S", ClassName.get(childModule).toString());
96	    }
97	
98	    StringBuilder indexerNameBuilder =
99	        new StringBuilder(INDEXER_NAME_PREFIX + annotation.getSimpleName() + "_");
100	    for (TypeElement element : sortedModules) {
101	      indexerNameBuilder.append(element.getQualifiedName().toString().replace(".", "_"));
102	      indexerNameBuilder.append("_");
103	    }
104	    indexerNameBuilder =
105	        new StringBuilder(indexerNameBuilder.substring(0, indexerNameBuilder.length() - 1));
106	    String indexerName = indexerNameBuilder.toString();
107	    // If the indexer name has too many packages/modules, it can exceed the file name length
108	    // allowed by the file system, which can break compilation. To avoid that, fall back to a
109	    // deterministic UUID.
110	    if (indexerName.length() >= (MAXIMUM_FILE_NAME_LENGTH - INDEXER_NAME_PREFIX.length())) {
111	      indexerName =
112	          INDEXER_NAME_PREFIX
113	              + UUID.nameUUIDFromBytes(indexerName.getBytes()).toString().replace("-", "_");
114	    }
115	
116	    return TypeSpec.classBuilder(indexerName)
117	        .addAnnotation(annotationBuilder.build())
118	        .addModifiers(Modifier.PUBLIC)
119	        .build();
120	  }
121	
122	  private static String getAnnotationValue(Class<? extends Annotation> annotation) {
123	    if (annotation == GlideModule.class) {
124	      return "modules";
125	    } else if (annotation == GlideExtension.class) {
126	      return "extensions";
127	    } else {
128	      throw new IllegalArgumentException("Unrecognized annotation: " + annotation);
129	    }
130	  }
131	}
