18	 * resource types, and/or extend Glide's API.
19	 *
20	 * <p>This processor discovers all {@code AppGlideModule} and {@code LibraryGlideModule}
21	 * implementations that are annotated with {@link com.bumptech.glide.annotation.GlideModule}. Any
22	 * implementations missing the annotation will be ignored.
23	 *
24	 * <p>This processor also discovers all {@link com.bumptech.glide.annotation.GlideExtension}
25	 * annotated classes.
26	 *
27	 * <p>Multiple classes are generated by this processor:
28	 *
29	 * <ul>
30	 *   <li>For {@code LibraryGlideModule}s - A GlideIndexer class in a specific package that will
31	 *       later be used by the processor to discover all {@code LibraryGlideModule} classes.
32	 *   <li>For {@code AppGlideModule}s - A single {@code AppGlideModule} implementation ({@code
33	 *       com.bumptech.glide.GeneratedAppGlideModule}) that calls all {@code LibraryGlideModule}s and
34	 *       the original {@code AppGlideModule} in the correct order when Glide is initialized.
35	 *   <li>{@link com.bumptech.glide.annotation.GlideExtension}s -
36	 *       <ul>
37	 *         <li>A {@code com.bumptech.glide.request.RequestOptions} implementation that contains
38	 *             static versions of all builder methods in the base class and both static and instance
39	 *             versions of methods in all {@link com.bumptech.glide.annotation.GlideExtension}s.
40	 *         <li>If one or more methods in one or more {@link
41	 *             com.bumptech.glide.annotation.GlideExtension} annotated classes are annotated with
42	 *             {@link GlideType}:
43	 *             <ul>
44	 *               <li>A {@code com.bumptech.glide.RequestManager} implementation containing a
45	 *                   generated method for each method annotated with {@link GlideType}.
46	 *               <li>A {@code
47	 *                   com.bumptech.glide.manager.RequestManagerRetriever.RequestManagerFactory}
48	 *                   implementation that produces the generated {@code
49	 *                   com.bumptech.glide.RequestManager}s.
50	 *               <li>A {@code com.bumptech.glide.Glide} look-alike that implements all static
51	 *                   methods in the {@code com.bumptech.glide.Glide} singleton and returns the
52	 *                   generated {@code com.bumptech.glide.RequestManager} implementation when
53	 *                   appropriate.
54	 *             </ul>
55	 *       </ul>
56	 * </ul>
57	 *
58	 * <p>{@code AppGlideModule} implementations must only be included in applications, not in
59	 * libraries. There must be exactly one {@code AppGlideModule} implementation per Application. The
60	 * {@code AppGlideModule} class is used as a signal that all modules have been found and that the
61	 * final merged {@code com.bumptech.glide.GeneratedAppGlideModule} impl can be created.
62	 */
63	@AutoService(Processor.class)
64	public final class GlideAnnotationProcessor extends AbstractProcessor {
65	  static final boolean DEBUG = false;
66	  private static final String USE_LEGACY_TYPE_COMPARISON_OPTION = "glide.useLegacyTypeComparison";
67	  private ProcessorUtil processorUtil;
68	  private LibraryModuleProcessor libraryModuleProcessor;
69	  private AppModuleProcessor appModuleProcessor;
70	  private boolean isGeneratedAppGlideModuleWritten;
71	  private ExtensionProcessor extensionProcessor;
72	  private boolean useLegacyTypeComparison;
73	
74	  @Override
75	  public synchronized void init(ProcessingEnvironment processingEnvironment) {
76	    super.init(processingEnvironment);
77	    processorUtil = new ProcessorUtil(processingEnvironment);
78	    IndexerGenerator indexerGenerator = new IndexerGenerator(processorUtil);
79	    libraryModuleProcessor = new LibraryModuleProcessor(processorUtil, indexerGenerator);
80	    appModuleProcessor = new AppModuleProcessor(processingEnvironment, processorUtil);
81	    useLegacyTypeComparison =
82	        Boolean.parseBoolean(
83	            processingEnvironment.getOptions().get(USE_LEGACY_TYPE_COMPARISON_OPTION));
84	    extensionProcessor =
85	        new ExtensionProcessor(
86	            processingEnvironment, processorUtil, indexerGenerator, useLegacyTypeComparison);
87	  }
88	
89	  @Override
90	  public Set<String> getSupportedOptions() {
91	    return ImmutableSet.of(USE_LEGACY_TYPE_COMPARISON_OPTION);
92	  }
93	
94	  @Override
95	  public Set<String> getSupportedAnnotationTypes() {
96	    Set<String> result = new HashSet<>();
97	    result.addAll(libraryModuleProcessor.getSupportedAnnotationTypes());
98	    result.addAll(extensionProcessor.getSupportedAnnotationTypes());
99	    return result;
100	  }
101	
102	  @Override
103	  public SourceVersion getSupportedSourceVersion() {
104	    return SourceVersion.latestSupported();
105	  }
106	
107	  /**
108	   * Each round we do the following:
109	   *
110	   * <ol>
111	   *   <li>Find all {@code AppGlideModule}s and save them to an instance variable (throw if > 1).
112	   *   <li>Find all {@code LibraryGlideModule}s
113	   *   <li>For each {@code LibraryGlideModule}, write an {@code Indexer} with an Annotation with the
114	   *       class name.
115	   *   <li>If we wrote any {@code Indexer}s, return and wait for the next round.
116	   *   <li>If we didn't write any {@code Indexer}s and there is a {@code AppGlideModule}, write the
117	   *       {@code GeneratedAppGlideModule}. Once the {@code GeneratedAppGlideModule} is written, we
118	   *       expect to be finished. Any further generation of related classes will result in errors.
119	   * </ol>
120	   */
121	  @Override
122	  public boolean process(Set<? extends TypeElement> set, RoundEnvironment env) {
123	    processorUtil.process();
124	    boolean newModulesWritten = libraryModuleProcessor.processModules(env);
125	    boolean newExtensionWritten = extensionProcessor.processExtensions(env);
126	    appModuleProcessor.processModules(set, env);
127	
128	    if (newExtensionWritten || newModulesWritten) {
129	      if (isGeneratedAppGlideModuleWritten) {
130	        throw new IllegalStateException("Cannot process annotations after writing AppGlideModule");
131	      }
132	      return false;
133	    }
134	
135	    if (!isGeneratedAppGlideModuleWritten) {
136	      isGeneratedAppGlideModuleWritten = appModuleProcessor.maybeWriteAppModule();
137	    }
138	    return false;
139	  }
140	}
