3	import com.bumptech.glide.annotation.GlideModule;
4	import com.squareup.javapoet.TypeSpec;
5	import java.util.ArrayList;
6	import java.util.Collections;
7	import java.util.List;
8	import java.util.Set;
9	import javax.annotation.processing.RoundEnvironment;
10	import javax.lang.model.element.TypeElement;
11	
12	/** Generates Indexer classes annotated with {@link Index} for all {@code LibraryGlideModule}s. */
13	final class LibraryModuleProcessor {
14	  private final ProcessorUtil processorUtil;
15	  private final IndexerGenerator indexerGenerator;
16	
17	  LibraryModuleProcessor(ProcessorUtil processorUtil, IndexerGenerator indexerGenerator) {
18	    this.processorUtil = processorUtil;
19	    this.indexerGenerator = indexerGenerator;
20	  }
21	
22	  boolean processModules(RoundEnvironment env) {
23	    // Order matters here, if we find an Indexer below, we return before writing the root module.
24	    // If we fail to add to appModules before then, we might accidentally skip a valid RootModule.
25	    List<TypeElement> libraryGlideModules = new ArrayList<>();
26	    for (TypeElement element : processorUtil.getElementsFor(GlideModule.class, env)) {
27	      // Root elements are added separately and must be checked separately because they're sub
28	      // classes of LibraryGlideModules.
29	      if (processorUtil.isAppGlideModule(element)) {
30	        continue;
31	      } else if (!processorUtil.isLibraryGlideModule(element)) {
32	        throw new IllegalStateException(
33	            "@GlideModule can only be applied to LibraryGlideModule"
34	                + " and AppGlideModule implementations, not: "
35	                + element);
36	      }
37	
38	      libraryGlideModules.add(element);
39	    }
40	
41	    processorUtil.debugLog("got child modules: " + libraryGlideModules);
42	    if (libraryGlideModules.isEmpty()) {
43	      return false;
44	    }
45	
46	    TypeSpec indexer = indexerGenerator.generate(libraryGlideModules);
47	    processorUtil.writeIndexer(indexer);
48	    processorUtil.debugLog(
49	        "Wrote an Indexer this round, skipping the app module to ensure all "
50	            + "indexers are found");
51	    // If I write an Indexer in a round in the target package, then try to find all classes in
52	    // the target package, my newly written Indexer won't be found. Since we wrote a class with
53	    // an Annotation handled by this processor, we know we will be called again in the next round
54	    // and we can safely wait to write our AppGlideModule until then.
55	    return true;
56	  }
57	
58	  Set<String> getSupportedAnnotationTypes() {
59	    return Collections.singleton(GlideModule.class.getName());
60	  }
61	}
