20	/**
21	 * Generates method overrides for classes that want to mix in {@link GlideOption} annotated methods
22	 * in Glide extensions.
23	 */
24	final class RequestOptionsExtensionGenerator {
25	  private TypeName containingClassName;
26	  private ProcessorUtil processorUtil;
27	
28	  RequestOptionsExtensionGenerator(TypeName containingClassName, ProcessorUtil processorUtil) {
29	    this.containingClassName = containingClassName;
30	    this.processorUtil = processorUtil;
31	  }
32	
33	  /**
34	   * Returns the set of {@link GlideOption} annotated methods in the classes that correspond to the
35	   * given extension class names.
36	   */
37	  List<ExecutableElement> getRequestOptionExtensionMethods(Set<String> glideExtensionClassNames) {
38	    return processorUtil.findAnnotatedElementsInClasses(
39	        glideExtensionClassNames, GlideOption.class);
40	  }
41	
42	  /**
43	   * Returns a list containing an override {@link MethodSpec} for all {@link GlideOption} annotated
44	   * methods in the classes that correspond to the given extension class names.
45	   */
46	  List<MethodSpec> generateInstanceMethodsForExtensions(Set<String> glideExtensionClassNames) {
47	    List<ExecutableElement> requestOptionExtensionMethods =
48	        getRequestOptionExtensionMethods(glideExtensionClassNames);
49	
50	    List<MethodSpec> result = new ArrayList<>(requestOptionExtensionMethods.size());
51	    for (ExecutableElement requestOptionsExtensionMethod : requestOptionExtensionMethods) {
52	      result.add(generateMethodsForRequestOptionsExtension(requestOptionsExtensionMethod));
53	    }
54	
55	    return result;
56	  }
57	
58	  private MethodSpec generateMethodsForRequestOptionsExtension(ExecutableElement element) {
59	    // Assert for legacy versions
60	    if (element.getReturnType().getKind() == TypeKind.VOID) {
61	      throw new IllegalArgumentException(
62	          "The "
63	              + element.getSimpleName()
64	              + " method annotated with @GlideOption in the "
65	              + element.getEnclosingElement().getSimpleName()
66	              + " @GlideExtension is using a legacy"
67	              + " format that is no longer supported. Please change your method definition so that"
68	              + " your @GlideModule annotated methods return BaseRequestOptions<?> objects instead"
69	              + " of null.");
70	    }
71	
72	    int overrideType = processorUtil.getOverrideType(element);
73	
74	    String methodName = element.getSimpleName().toString();
75	    MethodSpec.Builder builder =
76	        MethodSpec.methodBuilder(methodName)
77	            .addModifiers(Modifier.PUBLIC)
78	            .addJavadoc(processorUtil.generateSeeMethodJavadoc(element))
79	            .varargs(element.isVarArgs())
80	            .returns(containingClassName)
81	            .addAnnotation(
82	                AnnotationSpec.builder(SuppressWarnings.class)
83	                    .addMember("value", "$S", "unchecked")
84	                    .build());
85	
86	    // The 0th element is expected to be a RequestOptions object.
87	    List<? extends VariableElement> paramElements =
88	        element.getParameters().subList(1, element.getParameters().size());
89	    List<ParameterSpec> parameters = processorUtil.getParameters(paramElements);
90	    builder.addParameters(parameters);
91	
92	    String extensionRequestOptionsArgument;
93	    if (overrideType == OVERRIDE_EXTEND) {
94	      builder
95	          .addJavadoc(
96	              processorUtil.generateSeeMethodJavadoc(
97	                  containingClassName, methodName, paramElements))
98	          .addAnnotation(Override.class);
99	
100	      List<Object> methodArgs = new ArrayList<>();
101	      methodArgs.add(element.getSimpleName().toString());
102	      StringBuilder methodLiterals = new StringBuilder();
103	      if (!parameters.isEmpty()) {
104	        for (ParameterSpec parameter : parameters) {
105	          methodLiterals.append("$L, ");
106	          methodArgs.add(parameter.name);
107	        }
108	        methodLiterals =
109	            new StringBuilder(methodLiterals.substring(0, methodLiterals.length() - 2));
110	      }
111	      extensionRequestOptionsArgument =
112	          CodeBlock.builder()
113	              .add("super.$N(" + methodLiterals + ")", methodArgs.toArray(new Object[0]))
114	              .build()
115	              .toString();
116	    } else {
117	      extensionRequestOptionsArgument = "this";
118	    }
119	
120	    List<Object> args = new ArrayList<>();
121	    StringBuilder code = new StringBuilder("return ($T) $T.$L($L, ");
122	    args.add(containingClassName);
123	    args.add(ClassName.get(element.getEnclosingElement().asType()));
124	    args.add(element.getSimpleName().toString());
125	    args.add(extensionRequestOptionsArgument);
126	    if (!parameters.isEmpty()) {
127	      for (ParameterSpec parameter : parameters) {
128	        code.append("$L, ");
129	        args.add(parameter.name);
130	      }
131	    }
132	    code = new StringBuilder(code.substring(0, code.length() - 2));
133	    code.append(")");
134	    builder.addStatement(code.toString(), args.toArray(new Object[0]));
135	
136	    builder.addAnnotation(processorUtil.checkResult()).addAnnotation(processorUtil.nonNull());
137	
138	    return builder.build();
139	  }
140	}
