27	final class RequestOptionsOverrideGenerator {
28	
29	  private final TypeElement baseRequestOptionsType;
30	  private ProcessorUtil processorUtil;
31	
32	  RequestOptionsOverrideGenerator(
33	      ProcessingEnvironment processingEnv, ProcessorUtil processorUtil) {
34	
35	    this.processorUtil = processorUtil;
36	    baseRequestOptionsType =
37	        processingEnv.getElementUtils().getTypeElement(BASE_REQUEST_OPTIONS_QUALIFIED_NAME);
38	  }
