40	  List<MethodSpec> generateInstanceMethodOverridesForRequestOptions(TypeName typeToOverrideIn) {
41	    return generateInstanceMethodOverridesForRequestOptions(
42	        typeToOverrideIn, Collections.<String>emptySet());
43	  }
44	
45	  List<MethodSpec> generateInstanceMethodOverridesForRequestOptions(
46	      final TypeName typeToOverrideIn, final Set<String> excludedMethods) {
47	    return FluentIterable.from(
48	            processorUtil.findInstanceMethodsReturning(
49	                baseRequestOptionsType, baseRequestOptionsType))
50	        .filter(
51	            new Predicate<ExecutableElement>() {
52	              @Override
53	              public boolean apply(ExecutableElement input) {
54	                return !excludedMethods.contains(input.getSimpleName().toString());
55	              }
56	            })
57	        .transform(
58	            new Function<ExecutableElement, MethodSpec>() {
59	              @Override
60	              public MethodSpec apply(ExecutableElement input) {
61	                return generateRequestOptionOverride(typeToOverrideIn, input);
62	              }
63	            })
64	        .toList();
65	  }
66	
67	  private MethodSpec generateRequestOptionOverride(
68	      TypeName typeToOverrideIn, ExecutableElement methodToOverride) {
69	    MethodSpec.Builder result =
70	        processorUtil.overriding(methodToOverride).returns(typeToOverrideIn);
71	    result.addCode(
72	        CodeBlock.builder()
73	            .add("return ($T) super.$N(", typeToOverrideIn, methodToOverride.getSimpleName())
74	            .add(
75	                FluentIterable.from(result.build().parameters)
76	                    .transform(
77	                        new Function<ParameterSpec, String>() {
78	                          @Override
79	                          public String apply(ParameterSpec input) {
80	                            return input.name;
81	                          }
82	                        })
83	                    .join(Joiner.on(", ")))
84	            .add(");\n")
85	            .build());
86	
87	    if (methodToOverride.getSimpleName().toString().contains("transform")
88	        && methodToOverride.isVarArgs()) {
89	      result
90	          .addModifiers(Modifier.FINAL)
91	          .addAnnotation(SafeVarargs.class)
92	          .addAnnotation(
93	              AnnotationSpec.builder(SuppressWarnings.class)
94	                  .addMember("value", "$S", "varargs")
95	                  .build());
96	    }
97	
98	    for (AnnotationMirror mirror : methodToOverride.getAnnotationMirrors()) {
99	      result.addAnnotation(AnnotationSpec.get(mirror));
100	    }
101	
102	    return result.build();
103	  }
104	}
